use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct XmlNode {
    pub name: String,
    pub attributes: HashMap<String, String>,
    pub children: Vec<XmlNode>,
    pub text: String,
}

impl XmlNode {
    pub fn parse(s: &str) -> Result<XmlNode, String> {
        let mut pos = 0;
        let bytes = s.as_bytes();

        fn skip_whitespace_and_comments(bytes: &[u8], mut pos: usize) -> usize {
            loop {
                while pos < bytes.len() && (bytes[pos] == b' ' || bytes[pos] == b'\t' || bytes[pos] == b'\n' || bytes[pos] == b'\r') {
                    pos += 1;
                }
                if pos + 4 <= bytes.len() && &bytes[pos..pos+4] == b"<!--" {
                    pos += 4;
                    while pos + 3 <= bytes.len() && &bytes[pos..pos+3] != b"-->" {
                        pos += 1;
                    }
                    pos += 3;
                } else if pos + 2 <= bytes.len() && &bytes[pos..pos+2] == b"<?" {
                    pos += 2;
                    while pos + 2 <= bytes.len() && &bytes[pos..pos+2] != b"?>" {
                        pos += 1;
                    }
                    pos += 2;
                } else {
                    break;
                }
            }
            pos
        }

        fn parse_node(bytes: &[u8], pos: &mut usize) -> Result<XmlNode, String> {
            *pos = skip_whitespace_and_comments(bytes, *pos);
            if *pos >= bytes.len() || bytes[*pos] != b'<' {
                return Err("expected '<'".to_string());
            }
            *pos += 1; // skip '<'

            // Parse tag name
            let name_start = *pos;
            while *pos < bytes.len() && !bytes[*pos].is_ascii_whitespace() && bytes[*pos] != b'>' && bytes[*pos] != b'/' {
                *pos += 1;
            }
            let name = std::str::from_utf8(&bytes[name_start..*pos]).unwrap().to_string();

            // Parse attributes
            let mut attributes = HashMap::new();
            loop {
                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                if *pos >= bytes.len() || bytes[*pos] == b'>' || bytes[*pos] == b'/' {
                    break;
                }
                let attr_key_start = *pos;
                while *pos < bytes.len() && !bytes[*pos].is_ascii_whitespace() && bytes[*pos] != b'=' && bytes[*pos] != b'>' && bytes[*pos] != b'/' {
                    *pos += 1;
                }
                let attr_key = std::str::from_utf8(&bytes[attr_key_start..*pos]).unwrap().to_string();
                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                let mut attr_val = String::new();
                if *pos < bytes.len() && bytes[*pos] == b'=' {
                    *pos += 1;
                    while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                        *pos += 1;
                    }
                    if *pos < bytes.len() && (bytes[*pos] == b'"' || bytes[*pos] == b'\'') {
                        let quote = bytes[*pos];
                        *pos += 1;
                        let val_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != quote {
                            *pos += 1;
                        }
                        attr_val = std::str::from_utf8(&bytes[val_start..*pos]).unwrap().to_string();
                        if *pos < bytes.len() { *pos += 1; }
                    }
                }
                attributes.insert(attr_key, attr_val);
            }

            if *pos < bytes.len() && bytes[*pos] == b'/' {
                *pos += 1; // skip '/'
                if *pos < bytes.len() && bytes[*pos] == b'>' { *pos += 1; }
                return Ok(XmlNode { name, attributes, children: vec![], text: String::new() });
            }

            if *pos < bytes.len() && bytes[*pos] == b'>' {
                *pos += 1;
            }

            // Parse children and text
            let mut children = vec![];
            let mut text = String::new();

            loop {
                *pos = skip_whitespace_and_comments(bytes, *pos);
                if *pos >= bytes.len() { break; }

                if bytes[*pos] == b'<' {
                    if *pos + 1 < bytes.len() && bytes[*pos + 1] == b'/' {
                        // Closing tag
                        *pos += 2;
                        while *pos < bytes.len() && bytes[*pos] != b'>' {
                            *pos += 1;
                        }
                        if *pos < bytes.len() { *pos += 1; }
                        break;
                    } else {
                        children.push(parse_node(bytes, pos)?);
                    }
                } else {
                    let text_start = *pos;
                    while *pos < bytes.len() && bytes[*pos] != b'<' {
                        *pos += 1;
                    }
                    let t = std::str::from_utf8(&bytes[text_start..*pos]).unwrap().trim();
                    if !t.is_empty() {
                        if !text.is_empty() { text.push(' '); }
                        text.push_str(t);
                    }
                }
            }

            Ok(XmlNode { name, attributes, children, text })
        }

        pos = skip_whitespace_and_comments(bytes, pos);
        parse_node(bytes, &mut pos)
    }
}

fn main() {
    let svd = std::fs::read_to_string("/tmp/test.svd").unwrap();
    let node = XmlNode::parse(&svd).unwrap();
    println!("Root tag: {}", node.name);
    println!("Children count: {}", node.children.len());
}
EOF

cd /tmp/testxml && cargo run --offline
cd / && rm -rf /tmp/testxml
"}

