{"command":"mkdir -p src/generate

cat << 'EOF' > src/config.rs
use std::collections::BTreeMap;
use std::path::PathBuf;
use serde::{Deserialize, Serialize};
use url::Url;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Edition {
    #[serde(rename = "2021")]
    E2021,
    #[serde(rename = "2024")]
    E2024,
}

impl Default for Edition {
    fn default() -> Self {
        Edition::E2021
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Target {
    #[serde(rename = "cortex-m")]
    CortexM,
    #[serde(rename = "msp430")]
    Msp430,
    #[serde(rename = "riscv")]
    RISCV,
    #[serde(rename = "xtensa-lx")]
    XtensaLX,
    #[serde(rename = "mips")]
    Mips,
    #[serde(rename = "none")]
    None,
}

impl Default for Target {
    fn default() -> Self {
        Target::CortexM
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SourceType {
    #[serde(rename = "xml")]
    Xml,
    #[serde(rename = "yaml")]
    Yaml,
    #[serde(rename = "json")]
    Json,
}

impl Default for SourceType {
    fn default() -> Self {
        SourceType::Xml
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum IdentTheme {
    #[serde(rename = "legacy")]
    Legacy,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum IdentCase {
    Pascal,
    Constant,
    Snake,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct IdentFormat {
    pub case: Option<IdentCase>,
    pub prefix: String,
    pub suffix: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct IdentFormats(pub BTreeMap<String, IdentFormat>);

impl Default for IdentFormats {
    fn default() -> Self {
