        config.atomics = true;
    }
    if let Some(feature) = matches.get_one::<String>("atomics_feature") {
        config.atomics_feature = Some(feature.clone());
    }
    if matches.get_flag("ignore_groups") {
        config.ignore_groups = true;
    }
    if matches.get_flag("keep_list") {
        config.keep_list = true;
    }
    if matches.get_flag("generic_mod") {
        config.generic_mod = true;
    }
    if matches.get_flag("feature_group") {
        config.feature_group = true;
    }
    if matches.get_flag("feature_peripheral") {
        config.feature_peripheral = true;
    }
