                process::exit(1);
            }
        }
    }
    if let Some(fmts) = matches.get_many::<String>("ident_format") {
        for fmt in fmts {
            config.ident_formats.update_format(fmt);
        }
    }
    if matches.get_flag("field_names_for_enums") {
        config.field_names_for_enums = true;
    }
    if matches.get_flag("max_cluster_size") {
        config.max_cluster_size = true;
    }
    if matches.get_flag("impl_debug") {
