        config.skip_crate_attributes = true;
    }
    if matches.get_flag("strict") {
        config.strict = true;
    }
    if let Some(st_str) = matches.get_one::<String>("source_type") {
        match st_str.as_str() {
            "xml" => config.source_type = SourceType::Xml,
            "yaml" => config.source_type = SourceType::Yaml,
            "json" => config.source_type = SourceType::Json,
            _ => {
                eprintln!("[ERROR svd2rust] Failed to deserialize value");
                eprintln!("    ");
                eprintln!("    Caused by:");
                eprintln!("        unknown variant `{}`, expected one of `xml`, `yaml`, `json`", st_str);
                process::exit(1);
            }
        }
    }
    if matches.get_flag("reexport_core_peripherals") {
        config.reexport_core_peripherals = true;
    }
    if matches.get_flag("reexport_interrupt") {
        config.reexport_interrupt = true;
    }
    if let Some(shift_str) = matches.get_one::<String>("base_address_shift") {
        let shift = parse_number(shift_str).unwrap_or(0);
        config.base_address_shift = shift;
    }
    if let Some(log_str) = matches.get_one::<String>("log") {
        config.log_level = Some(log_str.clone());
    }

    // Initialize logger
    let log_level_filter = config
        .log_level
        .as_deref()
        .or_else(|| std::env::var("RUST_LOG").ok().as_deref())
        .unwrap_or("off");

    if log_level_filter != "off" {
        use std::io::Write;
        let mut builder = env_logger::Builder::new();
        builder.parse_filters(log_level_filter);
        builder.format(|buf, record| {
            let level_str = match record.level() {
                log::Level::Error => "ERROR",
                log::Level::Warn => "WARN ",
                log::Level::Info => "INFO ",
                log::Level::Debug => "DEBUG",
                log::Level::Trace => "TRACE",
            };
            writeln!(buf, "[{} {}] {}", level_str, record.target(), record.args())
        });
        builder.init();
    }

    log::debug!("Current svd2rust config: {:#?}", config);

    // Load settings file if specified
    if let Some(settings_path) = &config.settings_file {
        let content = match std::fs::read_to_string(settings_path) {
            Ok(c) => c,
            Err(e) => {
