use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct XmlNode {
    pub name: String,
    pub attributes: HashMap<String, String>,
    pub children: Vec<XmlNode>,
    pub text: String,
}

impl XmlNode {
    pub fn parse(s: &str) -> Result<XmlNode, String> {
        let bytes = s.as_bytes();
        let mut pos = 0;

        fn skip_ws_and_comments(bytes: &[u8], mut pos: usize) -> usize {
            loop {
                while pos < bytes.len()
                    && (bytes[pos] == b' '
                        || bytes[pos] == b'\t'
                        || bytes[pos] == b'\n'
                        || bytes[pos] == b'\r')
                {
                    pos += 1;
                }
                if pos + 4 <= bytes.len() && &bytes[pos..pos + 4] == b"<!--" {
                    pos += 4;
                    while pos + 3 <= bytes.len() && &bytes[pos..pos + 3] != b"-->" {
                        pos += 1;
                    }
                    pos += 3;
                } else if pos + 2 <= bytes.len() && &bytes[pos..pos + 2] == b"<?" {
                    pos += 2;
                    while pos + 2 <= bytes.len() && &bytes[pos..pos + 2] != b"?>" {
                        pos += 1;
                    }
                    pos += 2;
                } else {
                    break;
                }
            }
            pos
        }

        fn parse_node(bytes: &[u8], pos: &mut usize) -> Result<XmlNode, String> {
            *pos = skip_ws_and_comments(bytes, *pos);
            if *pos >= bytes.len() || bytes[*pos] != b'<' {
                return Err("the document does not have a root node".to_string());
            }
            *pos += 1; // skip '<'

            let name_start = *pos;
            while *pos < bytes.len()
                && !bytes[*pos].is_ascii_whitespace()
                && bytes[*pos] != b'>'
                && bytes[*pos] != b'/'
            {
                *pos += 1;
            }
            let name = std::str::from_utf8(&bytes[name_start..*pos])
                .map_err(|e| e.to_string())?
                .to_string();

            let mut attributes = HashMap::new();
            loop {
                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                if *pos >= bytes.len() || bytes[*pos] == b'>' || bytes[*pos] == b'/' {
                    break;
                }
                let attr_key_start = *pos;
                while *pos < bytes.len()
                    && !bytes[*pos].is_ascii_whitespace()
                    && bytes[*pos] != b'='
                    && bytes[*pos] != b'>'
                    && bytes[*pos] != b'/'
                {
                    *pos += 1;
                }
                let attr_key = std::str::from_utf8(&bytes[attr_key_start..*pos])
                    .map_err(|e| e.to_string())?
                    .to_string();

                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                let mut attr_val = String::new();
                if *pos < bytes.len() && bytes[*pos] == b'=' {
                    *pos += 1;
                    while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                        *pos += 1;
                    }
                    if *pos < bytes.len() && (bytes[*pos] == b'"' || bytes[*pos] == b'\'') {
                        let quote = bytes[*pos];
                        *pos += 1;
                        let val_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != quote {
                            *pos += 1;
                        }
                        attr_val = std::str::from_utf8(&bytes[val_start..*pos])
                            .map_err(|e| e.to_string())?
                            .to_string();
                        if *pos < bytes.len() {
                            *pos += 1;
                        }
                    }
                }
                attributes.insert(attr_key, attr_val);
            }

            if *pos < bytes.len() && bytes[*pos] == b'/' {
                *pos += 1;
                if *pos < bytes.len() && bytes[*pos] == b'>' {
                    *pos += 1;
                }
                return Ok(XmlNode {
                    name,
                    attributes,
                    children: vec![],
                    text: String::new(),
                });
            }

            if *pos < bytes.len() && bytes[*pos] == b'>' {
                *pos += 1;
            }

            let mut children = vec![];
            let mut text = String::new();

            loop {
                *pos = skip_ws_and_comments(bytes, *pos);
                if *pos >= bytes.len() {
                    break;
                }

                if bytes[*pos] == b'<' {
                    if *pos + 1 < bytes.len() && bytes[*pos + 1] == b'/' {
                        // Closing tag
                        *pos += 2;
                        let tag_close_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != b'>' {
                            *pos += 1;
                        }
                        let close_name = std::str::from_utf8(&bytes[tag_close_start..*pos])
                            .unwrap_or("")
                            .trim();
                        if close_name != name {
                            return Err(format!("expected '{}' tag, not '{}'", name, close_name));
                        }
                        if *pos < bytes.len() {
                            *pos += 1;
                        }
                        break;
                    } else {
                        children.push(parse_node(bytes, pos)?);
                    }
                } else {
                    let text_start = *pos;
                    while *pos < bytes.len() && bytes[*pos] != b'<' {
                        *pos += 1;
                    }
                    let t = std::str::from_utf8(&bytes[text_start..*pos])
                        .unwrap_or("")
                        .trim();
                    if !t.is_empty() {
                        if !text.is_empty() {
                            text.push(' ');
                        }
                        text.push_str(t);
                    }
                }
            }

            Ok(XmlNode {
                name,
                attributes,
                children,
                text,
            })
        }

        pos = skip_ws_and_comments(bytes, pos);
        let node = parse_node(bytes, &mut pos)?;
        if node.name != "device" {
            return Err(format!("expected 'device' tag, not '{}'", node.name));
        }
        Ok(node)
    }

    pub fn child_text(&self, name: &str) -> Option<String> {
        self.children
            .iter()
            .find(|c| c.name == name)
            .map(|c| c.text.clone())
    }

    pub fn children_named<'a>(&'a self, name: &'a str) -> impl Iterator<Item = &'a XmlNode> {
        self.children.iter().filter(move |c| c.name == name)
    }

    pub fn attr(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|s| s.as_str())
    }
}

pub fn parse_svd_number(s: &str) -> Result<u64, String> {
    let s = s.trim().replace('_', "");
    if let Some(stripped) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(stripped, 16).map_err(|e| e.to_string())
    } else if let Some(stripped) = s.strip_prefix("0b").or_else(|| s.strip_prefix("0B")) {
        u64::from_str_radix(stripped, 2).map_err(|e| e.to_string())
    } else if let Some(stripped) = s.strip_prefix('#') {
        u64::from_str_radix(stripped, 2).map_err(|e| e.to_string())
    } else {
        s.parse::<u64>().map_err(|e| e.to_string())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Access {
    ReadOnly,
    WriteOnly,
    ReadWrite,
    WriteOnce,
    ReadWriteOnce,
}

impl Access {
    pub fn parse(s: &str) -> Option<Self> {
        match s.trim() {
            "read-only" => Some(Access::ReadOnly),
            "write-only" => Some(Access::WriteOnly),
            "read-write" => Some(Access::ReadWrite),
            "writeOnce" => Some(Access::WriteOnce),
            "read-writeOnce" => Some(Access::ReadWriteOnce),
            _ => None,
        }
    }
}

