            }
        }

        impl<REG> W<REG>
        where
            REG: Writable<Safety = Safe>,
        {
            #[doc = " Writes raw bits to the register."]
            #[inline(always)]
            pub fn set(&mut self, bits: REG::Ux) -> &mut Self {
                self.bits = bits;
                self
            }
        }

        #[doc = " Field reader."]
        #[doc = ""]
        #[doc = " Result of the `read` methods of fields."]
        pub type FieldReader<FI = u8> = raw::FieldReader<FI>;

        #[doc = " Bit-wise field reader"]
        pub type BitReader<FI = bool> = raw::BitReader<FI>;

        impl<FI: FieldSpec> FieldReader<FI> {
            #[doc = " Reads raw bits from field."]
            #[inline(always)]
            pub const fn bits(&self) -> FI::Ux {
                self.bits
            }
        }

        impl<FI: FieldSpec> core::fmt::Debug for FieldReader<FI> {
            fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
                core::fmt::Debug::fmt(&self.bits, f)
            }
        }

        impl<FI> PartialEq<FI> for FieldReader<FI>
        where
            FI: FieldSpec + Copy,
        {
            #[inline(always)]
            fn eq(&self, other: &FI) -> bool {
                self.bits.eq(&FI::Ux::from(*other))
            }
        }

        impl<FI> PartialEq<FI> for BitReader<FI>
        where
            FI: Copy,
            bool: From<FI>,
        {
            #[inline(always)]
            fn eq(&self, other: &FI) -> bool {
                self.bits.eq(&bool::from(*other))
            }
        }

        impl<FI> BitReader<FI> {
            #[doc = " Value of the field as raw bits."]
            #[inline(always)]
            pub const fn bit(&self) -> bool {
                self.bits
            }

            #[doc = " Returns `true` if the bit is clear (0)."]
            #[inline(always)]
            pub const fn bit_is_clear(&self) -> bool {
                !self.bit()
            }

            #[doc = " Returns `true` if the bit is set (1)."]
            #[inline(always)]
            pub const fn bit_is_set(&self) -> bool {
                self.bit()
            }
        }

        #atomic_mod
    }
}
EOF
"}

{"command":"cat << 'EOF' > src/generate/util.rs
use heck::{ToPascalCase, ToShoutySnakeCase, ToSnakeCase};
use proc_macro2::Ident;
use syn::parse_str;
use crate::config::{Config, IdentCase};

pub fn format_ident(name: &str, ident_type: &str, config: &Config) -> String {
    let fmt = config.ident_formats.0.get(ident_type);
    let (case, prefix, suffix) = if let Some(f) = fmt {
        (f.case, f.prefix.as_str(), f.suffix.as_str())
    } else {
        (None, "", "")
    };

    let cased = match case {
        Some(IdentCase::Pascal) => name.to_pascal_case(),
        Some(IdentCase::Constant) => name.to_shouty_snake_case(),
        Some(IdentCase::Snake) => name.to_snake_case(),
        None => name.to_string(),
    };

    format!("{}{}{}", prefix, cased, suffix)
}

pub fn make_ident(name: &str) -> Ident {
    let sanitized = match name {
        "as" | "break" | "const" | "continue" | "crate" | "else" | "enum" | "extern"
        | "false" | "fn" | "for" | "if" | "impl" | "in" | "let" | "loop" | "match"
        | "mod" | "move" | "mut" | "pub" | "ref" | "return" | "self" | "Self"
        | "static" | "struct" | "super" | "trait" | "true" | "type" | "unsafe" | "use"
        | "where" | "while" | "async" | "await" | "dyn" | "abstract" | "become" | "box"
        | "do" | "final" | "macro" | "override" | "priv" | "typeof" | "unsized" | "virtual"
        | "yield" | "try" => format!("r#{}", name),
        _ => name.to_string(),
    };
    parse_str::<Ident>(&sanitized).unwrap_or_else(|_| Ident::new("invalid_ident", proc_macro2::Span::call_site()))
}
EOF
"}

