{"command":"cat << 'EOF' > src/generate/field.rs
use proc_macro2::TokenStream;
use quote::quote;
use syn::Ident;
use crate::config::Config;
use crate::svd::{Access, Field};
use crate::generate::util::{format_ident, make_ident};

pub struct FieldRenderResult {
    pub reader_typedefs: TokenStream,
    pub writer_typedefs: TokenStream,
    pub r_impl_methods: TokenStream,
    pub w_impl_methods: TokenStream,
    pub enum_defs: TokenStream,
}

pub fn render_field(
    field: &Field,
    reg_spec_ident: &Ident,
    reg_access: Option<Access>,
    config: &Config,
) -> FieldRenderResult {
    let raw_field_name = &field.name;
    let accessor_name = format_ident(raw_field_name, "field_accessor", config);
    let accessor_ident = make_ident(&accessor_name);

    let reader_name = format_ident(raw_field_name, "field_reader", config);
    let reader_ident = make_ident(&reader_name);

    let writer_name = format_ident(raw_field_name, "field_writer", config);
    let writer_ident = make_ident(&writer_name);

    let is_bit = field.bit_width == 1;
    let offset = field.bit_offset as u8;
    let width = field.bit_width as u8;

    let field_doc = field.description.as_deref().unwrap_or("");

    let mut reader_typedefs = quote! {};
    let mut writer_typedefs = quote! {};
    let mut r_impl_methods = quote! {};
    let mut w_impl_methods = quote! {};
    let mut enum_defs = quote! {};

    let access = field.access.or(reg_access).unwrap_or(Access::ReadWrite);

    let can_read = access == Access::ReadOnly || access == Access::ReadWrite || access == Access::ReadWriteOnce;
    let can_write = access == Access::WriteOnly || access == Access::ReadWrite || access == Access::WriteOnce || access == Access::ReadWriteOnce;

    // Check if enumeratedValues are present
    let mut enum_type_ident: Option<Ident> = None;
    if !field.enumerated_values.is_empty() {
        for evs in &field.enumerated_values {
            if !evs.values.is_empty() {
                let enum_raw_name = evs.name.as_deref().unwrap_or(raw_field_name);
                let enum_formatted_name = format_ident(enum_raw_name, "enum_name", config);
                let e_ident = make_ident(&enum_formatted_name);
                enum_type_ident = Some(e_ident.clone());

                let ux_type = if width <= 8 {
                    quote! { u8 }
                } else if width <= 16 {
                    quote! { u16 }
                } else if width <= 32 {
                    quote! { u32 }
                } else {
                    quote! { u64 }
                };

                let mut variants = quote! {};
                let mut match_arms = quote! {};
                let mut w_helpers = quote! {};
                let mut r_helpers = quote! {};

                for ev in &evs.values {
                    let v_raw_name = &ev.name;
                    let v_formatted_name = format_ident(v_raw_name, "enum_value", config);
                    let v_ident = make_ident(&v_formatted_name);
                    let v_doc = ev.description.as_deref().unwrap_or("");

                    if let Some(val) = ev.value {
                        let val_lit = proc_macro2::Literal::u64_unsuffixed(val);
                        variants.extend(quote! {
                            #[doc = #v_doc]
                            #v_ident = #val_lit,
                        });

                        match_arms.extend(quote! {
                            #val_lit => Some(#e_ident :: #v_ident),
                        });

                        let is_method_name = format_ident(&format!("is_{}", v_raw_name.to_lowercase()), "enum_value_accessor", config);
                        let is_method_ident = make_ident(&is_method_name);
                        r_helpers.extend(quote! {
                            #[doc = #v_doc]
                            #[inline(always)]
                            pub fn #is_method_ident(&self) -> bool {
                                *self == #e_ident :: #v_ident
                            }
                        });

                        let w_method_name = format_ident(v_raw_name, "enum_value_accessor", config);
                        let w_method_ident = make_ident(&w_method_name);
                        w_helpers.extend(quote! {
                            #[doc = #v_doc]
                            #[inline(always)]
                            pub fn #w_method_ident(self) -> &'a mut crate::W<REG> {
                                self.variant(#e_ident :: #v_ident)
                            }
                        });
                    }
                }

                enum_defs.extend(quote! {
                    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
                    #[repr(#ux_type)]
                    pub enum #e_ident {
                        #variants
                    }

                    impl From<#e_ident> for #ux_type {
                        #[inline(always)]
                        fn from(variant: #e_ident) -> Self {
                            variant as _
                        }
                    }

                    impl crate::FieldSpec for #e_ident {
                        type Ux = #ux_type;
                    }

                    impl crate::IsEnum for #e_ident {}
                });

                if can_read {
                    reader_typedefs.extend(quote! {
                        impl #reader_ident {
                            #[doc = "Get enumerated values variant"]
                            #[inline(always)]
                            pub const fn variant(&self) -> Option<#e_ident> {
                                match self.bits {
                                    #match_arms
                                    _ => None,
                                }
                            }
                            #r_helpers
                        }
                    });
                }

                if can_write {
                    writer_typedefs.extend(quote! {
                        impl<'a, REG> #writer_ident<'a, REG>
                        where
                            REG: crate::Writable + crate::RegisterSpec,
                            REG::Ux: From<#ux_type>,
                        {
                            #w_helpers
                        }
                    });
                }

                break;
            }
        }
    }

    if can_read {
        if is_bit {
            reader_typedefs.extend(quote! {
                #[doc = #field_doc]
                pub type #reader_ident = crate::BitReader;
            });
            r_impl_methods.extend(quote! {
                #[doc = #field_doc]
                #[inline(always)]
                pub fn #accessor_ident(&self) -> #reader_ident {
                    #reader_ident::new((self.bits & (1 << #offset)) != 0)
                }
            });
        } else {
            let field_type = if let Some(e_ident) = &enum_type_ident {
                quote! { #e_ident }
            } else if width <= 8 {
                quote! { u8 }
            } else if width <= 16 {
                quote! { u16 }
            } else if width <= 32 {
                quote! { u32 }
            } else {
                quote! { u64 }
            };

            reader_typedefs.extend(quote! {
                #[doc = #field_doc]
                pub type #reader_ident = crate::FieldReader<#field_type>;
            });

            let mask = (1u64 << width) - 1;
            let mask_lit = proc_macro2::Literal::u64_unsuffixed(mask);

            let body = if offset == 0 {
                quote! { (self.bits & #mask_lit) as #field_type }
            } else {
                quote! { ((self.bits >> #offset) & #mask_lit) as #field_type }
            };

            r_impl_methods.extend(quote! {
                #[doc = #field_doc]
                #[inline(always)]
                pub fn #accessor_ident(&self) -> #reader_ident {
                    #reader_ident::new(#body)
                }
            });
        }
    }

    if can_write {
        if is_bit {
            writer_typedefs.extend(quote! {
                #[doc = #field_doc]
                pub type #writer_ident<'a, REG> = crate::BitWriter<'a, REG>;
            });
            w_impl_methods.extend(quote! {
                #[doc = #field_doc]
                #[inline(always)]
                pub fn #accessor_ident(&mut self) -> #writer_ident<'_, #reg_spec_ident> {
                    #writer_ident::new(self, #offset)
                }
            });
        } else {
            let field_type = if let Some(e_ident) = &enum_type_ident {
                quote! { #e_ident }
            } else if width <= 8 {
                quote! { u8 }
            } else if width <= 16 {
                quote! { u16 }
            } else if width <= 32 {
                quote! { u32 }
            } else {
                quote! { u64 }
            };

            writer_typedefs.extend(quote! {
                #[doc = #field_doc]
                pub type #writer_ident<'a, REG> = crate::FieldWriter<'a, REG, #width, #field_type>;
            });

            w_impl_methods.extend(quote! {
                #[doc = #field_doc]
                #[inline(always)]
                pub fn #accessor_ident(&mut self) -> #writer_ident<'_, #reg_spec_ident> {
                    #writer_ident::new(self, #offset)
                }
            });
        }
    }

    FieldRenderResult {
        reader_typedefs,
        writer_typedefs,
        r_impl_methods,
        w_impl_methods,
        enum_defs,
    }
}
EOF
"}

