                let accessor_type_name = format_ident(&clean_reg_name, "register", config);
                let accessor_type_ident = make_ident(&accessor_type_name);

                let method_name = format_ident(&clean_reg_name, "register_accessor", config);
                let method_ident = make_ident(&method_name);
                let reg_doc = reg.description.as_deref().unwrap_or(&clean_reg_name);

                if let Some(dim) = &reg.dim {
                    let count = dim.dim as usize;
                    let count_lit = proc_macro2::Literal::usize_unsuffixed(count);

                    if let Some(dim_indices) = &dim.dim_index {
                        if dim_indices.len() == count && dim_indices.iter().any(|idx| idx.parse::<usize>().is_err()) {
                            // Non-numeric index (e.g. A, B, C)
                            rb_fields.extend(quote! {
                                #field_ident: [#accessor_type_ident; #count_lit],
                            });

                            let iter_method_name = format_ident(&format!("{}_iter", clean_reg_name), "register_accessor", config);
                            let iter_method_ident = make_ident(&iter_method_name);

                            rb_methods.extend(quote! {
                                #[doc = #reg_doc]
                                #[inline(always)]
                                pub const fn #field_ident(&self, n: usize) -> &#accessor_type_ident {
                                    &self.#field_ident[n]
                                }

                                #[doc = "Iterator for array of:"]
                                #[doc = #reg_doc]
                                #[inline(always)]
                                pub fn #iter_method_ident(&self) -> impl Iterator<Item = &#accessor_type_ident> {
                                    self.#field_ident.iter()
                                }
                            });

                            for (idx_n, idx_str) in dim_indices.iter().enumerate() {
                                let sub_method_raw = reg.name.replace("[%s]", idx_str).replace("%s", idx_str);
                                let sub_method_name = format_ident(&sub_method_raw, "register_accessor", config);
                                let sub_method_ident = make_ident(&sub_method_name);
                                let idx_lit = proc_macro2::Literal::usize_unsuffixed(idx_n);

                                rb_methods.extend(quote! {
                                    #[doc = #reg_doc]
                                    #[inline(always)]
                                    pub const fn #sub_method_ident(&self) -> &#accessor_type_ident {
                                        self.#field_ident(#idx_lit)
                                    }
                                });
                            }

                            current_offset += count as u64 * dim.dim_increment;
                            continue;
                        }
                    }

                    rb_fields.extend(quote! {
                        #field_ident: [#accessor_type_ident; #count_lit],
                    });

                    let iter_method_name = format_ident(&format!("{}_iter", clean_reg_name), "register_accessor", config);
                    let iter_method_ident = make_ident(&iter_method_name);

                    rb_methods.extend(quote! {
                        #[doc = #reg_doc]
                        #[inline(always)]
                        pub const fn #method_ident(&self, n: usize) -> &#accessor_type_ident {
                            &self.#field_ident[n]
                        }

                        #[doc = "Iterator for array of:"]
                        #[doc = #reg_doc]
                        #[inline(always)]
                        pub fn #iter_method_ident(&self) -> impl Iterator<Item = &#accessor_type_ident> {
                            self.#field_ident.iter()
                        }
                    });

                    current_offset += count as u64 * dim.dim_increment;
                } else {
                    rb_fields.extend(quote! {
                        #field_ident: #accessor_type_ident,
                    });

                    rb_methods.extend(quote! {
                        #[doc = #reg_doc]
                        #[inline(always)]
                        pub const fn #method_ident(&self) -> &#accessor_type_ident {
                            &self.#field_ident
                        }
                    });

                    current_offset += size_bytes;
                }
            }
            RegisterCluster::Cluster(cluster) => {
                let offset = cluster.address_offset;
                if offset > current_offset {
                    let gap = offset - current_offset;
                    let gap_lit = proc_macro2::Literal::u64_unsuffixed(gap);
                    let res_ident = make_ident(&format!("_reserved{}", reserved_count));
                    reserved_count += 1;
                    rb_fields.extend(quote! {
                        #res_ident: [u8; #gap_lit],
                    });
                    current_offset = offset;
                }

                let clean_cluster_name = cluster.name.replace("[%s]", "").replace("%s", "");
                let cluster_field_name = format_ident(&clean_cluster_name, "cluster_accessor", config);
                let cluster_field_ident = make_ident(&cluster_field_name);

                let cluster_mod_name = format_ident(&clean_cluster_name, "cluster_mod", config);
                let cluster_mod_ident = make_ident(&cluster_mod_name);

                let cluster_type_name = format_ident(&clean_cluster_name, "cluster", config);
                let cluster_type_ident = make_ident(&cluster_type_name);

                let cluster_doc = cluster.description.as_deref().unwrap_or(&clean_cluster_name);

                if let Some(dim) = &cluster.dim {
                    let count = dim.dim as usize;
                    let count_lit = proc_macro2::Literal::usize_unsuffixed(count);
                    let inc = dim.dim_increment;
                    let inc_lit = proc_macro2::Literal::u64_unsuffixed(inc);

                    rb_fields.extend(quote! {
                        #cluster_field_ident: (),
                    });

                    let iter_method_name = format_ident(&format!("{}_iter", clean_cluster_name), "cluster_accessor", config);
                    let iter_method_ident = make_ident(&iter_method_name);

                    rb_methods.extend(quote! {
                        #[doc = #cluster_doc]
                        #[inline(always)]
                        pub const fn #cluster_field_ident(&self, n: usize) -> &#cluster_mod_ident :: #cluster_type_ident {
                            #[allow(clippy::no_effect)]
                            [(); #count_lit][n];
                            unsafe {
                                &*core::ptr::from_ref(self)
                                    .cast::<u8>()
                                    .add(#inc_lit as usize * n)
                                    .cast()
                            }
                        }

                        #[doc = "Iterator for array of:"]
                        #[doc = #cluster_doc]
                        #[inline(always)]
                        pub fn #iter_method_ident(&self) -> impl Iterator<Item = &#cluster_mod_ident :: #cluster_type_ident> {
                            (0..#count_lit).map(move |n| unsafe {
                                &*core::ptr::from_ref(self)
                                    .cast::<u8>()
                                    .add(#inc_lit as usize * n)
                                    .cast()
                            })
                        }
                    });

                    current_offset += count as u64 * inc;
                } else {
                    rb_fields.extend(quote! {
                        #cluster_field_ident: #cluster_mod_ident :: #cluster_type_ident,
                    });

                    rb_methods.extend(quote! {
                        #[doc = #cluster_doc]
                        #[inline(always)]
                        pub const fn #cluster_field_ident(&self) -> &#cluster_mod_ident :: #cluster_type_ident {
                            &self.#cluster_field_ident
                        }
                    });
                }
            }
        }
    }

    quote! {
        #[doc = #periph_doc]
        pub type #periph_type_ident = crate::Periph<#periph_spec_ident>;

        pub struct #periph_spec_ident;

        impl crate::PeripheralSpec for #periph_spec_ident {
            type RB = #periph_mod_ident :: RegisterBlock;
            const ADDRESS: usize = #base_addr_lit;
            const NAME: &'static str = #raw_periph_name;
        }

        #[doc = #periph_doc]
        pub mod #periph_mod_ident {
            #[repr(C)]
            #[doc = "Register block"]
            pub struct RegisterBlock {
                #rb_fields
            }

            impl RegisterBlock {
                #rb_methods
            }

            #reg_typedefs
            #reg_mods
        }
    }
}
EOF
"}

{"command":"cat << 'EOF' > src/generate/device.rs
use proc_macro2::TokenStream;
use quote::quote;
use syn::Ident;
use crate::config::{Config, Target};
use crate::svd::{Device, Interrupt};
use crate::generate::util::{format_ident, make_ident};
use crate::generate::peripheral::render_peripheral;
use crate::generate::generic;

pub struct DeviceRenderResult {
    pub main_file_name: String, // "lib.rs" or "mod.rs"
    pub main_file_content: String,
    pub generic_file_content: Option<String>,
    pub device_x_content: Option<String>,
    pub build_rs_content: Option<String>,
}

pub fn render_device(device: &Device, config: &Config) -> DeviceRenderResult {
    log::info!("Rendering device");

    let device_name = &device.name;

    // Collect all interrupts
    let mut interrupts = vec![];
    for p in &device.peripherals {
        for int in &p.interrupts {
            interrupts.push(int.clone());
        }
    }
    interrupts.sort_by_key(|i| i.value);
    interrupts.dedup_by_key(|i| i.value);

    // 1. Crate attributes
    let doc_comment = format!(
        "Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust",
        device_name.to_uppercase()
    );

    let crate_attrs = if !config.skip_crate_attributes && !config.make_mod {
        quote! {
            #![doc = #doc_comment]
            #![allow(non_camel_case_types)]
            #![allow(non_snake_case)]
            #![no_std]
            #![cfg_attr(docsrs, feature(doc_cfg))]
        }
    } else if !config.skip_crate_attributes && config.make_mod {
        quote! {
            #![doc = #doc_comment]
        }
    } else {
        quote! {}
    };

    // 2. Generic mod
    let (generic_import, generic_file_content) = if config.generic_mod {
        let generic_ts = generic::render(config);
        (
            quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc = "Common register and bit access and modify traits"]
                pub mod generic;
            },
            Some(generic_ts.to_string()),
        )
    } else {
        let generic_ts = generic::render(config);
        (
            quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc = "Common register and bit access and modify traits"]
                pub mod generic {
                    #generic_ts
                }
            },
            None,
        )
    };

    // 3. Render Peripherals struct
    let mut periph_fields = quote! {};
    let mut periph_inits = quote! {};
    let mut periph_mods = quote! {};

    for p in &device.peripherals {
        let raw_p_name = &p.name;
        let field_name = format_ident(raw_p_name, "peripheral_singleton", config);
        let field_ident = make_ident(&field_name);

        let type_name = format_ident(raw_p_name, "peripheral", config);
        let type_ident = make_ident(&type_name);

        let p_doc = p.description.as_deref().unwrap_or(raw_p_name);

        periph_fields.extend(quote! {
            #[doc = #p_doc]
            pub #field_ident: #type_ident,
        });

        periph_inits.extend(quote! {
            #field_ident: #type_ident::steal(),
        });

        periph_mods.extend(render_peripheral(p, config));
    }

    let peripherals_struct = quote! {
        #[no_mangle]
        static mut DEVICE_PERIPHERALS: bool = false;

        #[doc = " All the peripherals."]
        #[allow(non_snake_case)]
        pub struct Peripherals {
            #periph_fields
        }

        impl Peripherals {
            #[doc = " Returns all the peripherals *once*."]
            #[cfg(feature = "critical-section")]
            #[inline]
            pub fn take() -> Option<Self> {
                critical_section::with(|_| {
                    if unsafe { DEVICE_PERIPHERALS } {
                        return None;
                    }
                    Some(unsafe { Peripherals::steal() })
                })
            }

            #[doc = " Unchecked version of `Peripherals::take`."]
            #[doc = ""]
            #[doc = " # Safety"]
            #[doc = ""]
            #[doc = " Each of the returned peripherals must be used at most once."]
            #[inline]
            pub unsafe fn steal() -> Self {
                DEVICE_PERIPHERALS = true;
                Peripherals {
                    #periph_inits
                }
            }
        }
    };

    // 4. Render Interrupt enum and vector table
    let interrupt_code = render_interrupts(&interrupts, config);

    let main_ts = quote! {
        #crate_attrs
        #generic_import
        #interrupt_code
        #periph_mods
        #peripherals_struct
    };

    let main_file_name = if config.make_mod {
        "mod.rs".to_string()
    } else {
        "lib.rs".to_string()
    };

    let (device_x_content, build_rs_content) = if matches!(
        config.target,
        Target::CortexM | Target::Msp430 | Target::RISCV | Target::XtensaLX
    ) {
        let mut dev_x = String::new();
        for int in &interrupts {
            let int_name = format_ident(&int.name, "interrupt", config);
            dev_x.push_str(&format!("PROVIDE({} = DefaultHandler);\n", int_name));
        }

        let build_rs_ts = quote! {
            #![doc = r" Builder file for Peripheral access crate generated by svd2rust tool"]
            use std::env;
            use std::fs::File;
            use std::io::Write;
            use std::path::PathBuf;

            fn main() {
                if env::var_os("CARGO_FEATURE_RT").is_some() {
                    let out = &PathBuf::from(env::var_os("OUT_DIR").unwrap());
                    File::create(out.join("device.x"))
                        .unwrap()
                        .write_all(include_bytes!("device.x"))
                        .unwrap();
                    println!("cargo:rustc-link-search={}", out.display());
                    println!("cargo:rerun-if-changed=device.x");
                }
                println!("cargo:rerun-if-changed=build.rs");
            }
        };

        (Some(dev_x), Some(build_rs_ts.to_string()))
    } else {
        (None, None)
    };

    DeviceRenderResult {
        main_file_name,
        main_file_content: main_ts.to_string(),
        generic_file_content,
        device_x_content,
        build_rs_content,
    }
}

fn render_interrupts(interrupts: &[Interrupt], config: &Config) -> TokenStream {
    if interrupts.is_empty() {
        if config.target == Target::CortexM {
            return quote! {
                #[cfg(feature = "rt")]
                extern "C" {}

                #[doc(hidden)]
                #[repr(C)]
                pub union Vector {
                    _handler: unsafe extern "C" fn(),
                    _reserved: u32,
                }

                #[cfg(feature = "rt")]
                #[doc(hidden)]
                #[link_section = ".vector_table.interrupts"]
                #[no_mangle]
                pub static __INTERRUPTS: [Vector; 0] = [];

                #[doc = "Enumeration of all the interrupts."]
                #[derive(Copy, Clone, Debug, PartialEq, Eq)]
                pub enum Interrupt {}

                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 {
                        match self {}
                    }
                }
            };
        } else {
            return quote! {};
        }
    }

    let mut variants = quote! {};
    let mut try_from_arms = quote! {};

    for int in interrupts {
        let int_name = format_ident(&int.name, "interrupt", config);
        let int_ident = make_ident(&int_name);
        let val_lit = proc_macro2::Literal::u16_unsuffixed(int.value);
        let doc = format!("{} - {}", int.value, int.description.as_deref().unwrap_or(""));

        variants.extend(quote! {
            #[doc = #doc]
            #int_ident = #val_lit,
        });

        try_from_arms.extend(quote! {
            #val_lit => Ok(Interrupt::#int_ident),
        });
    }

    match config.target {
        Target::CortexM => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }

                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 {
                        self as u16
                    }
                }
            }
        }
        Target::None => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }

                #[doc = r" TryFromInterruptError"]
                #[derive(Debug, Copy, Clone)]
                pub struct TryFromInterruptError(());

                impl Interrupt {
                    #[doc = r" Attempt to convert a given value into an `Interrupt`"]
                    #[inline]
                    pub fn try_from(value: u8) -> Result<Self, TryFromInterruptError> {
                        match value {
                            #try_from_arms
                            _ => Err(TryFromInterruptError(())),
                        }
                    }
                }

                pub use self::interrupt::Interrupt;
            }
        }
        _ => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }
            }
        }
    }
}
EOF
"}

