                eprintln!("    Caused by:");
                eprintln!("        {}", e);
                process::exit(1);
            }
        };
        config = match toml::from_str(&content) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("[ERROR svd2rust] Failed to parse config file");
                eprintln!("    ");
                eprintln!("    Caused by:");
                eprintln!("        {}", e);
                process::exit(1);
            }
        };
    }

    if let Some(input) = matches.get_one::<PathBuf>("input") {
        config.input = Some(input.clone());
    }
    if let Some(output_dir) = matches.get_one::<PathBuf>("output_dir") {
        config.output_dir = Some(output_dir.clone());
    }
    if let Some(settings) = matches.get_one::<PathBuf>("settings") {
        config.settings_file = Some(settings.clone());
    }
    if let Some(edition_str) = matches.get_one::<String>("edition") {
        match edition_str.as_str() {
            "2021" => config.edition = Edition::E2021,
