                eprintln!("    Caused by:");
                eprintln!("        unknown variant `{}`, expected one of `cortex-m`, `msp430`, `riscv`, `xtensa-lx`, `mips`, `none`", target_str);
                process::exit(1);
            }
        }
    }
    if matches.get_flag("atomics") {
