        config.generic_mod = true;
    }
    if matches.get_flag("feature_group") {
        config.feature_group = true;
    }
    if matches.get_flag("feature_peripheral") {
        config.feature_peripheral = true;
    }
    if let Some(theme_str) = matches.get_one::<String>("ident_formats_theme") {
        match theme_str.as_str() {
            "legacy" => {
