            writeln!(buf, "[{} {}] {}", level_str, record.target(), record.args())
        });
        builder.init();
    }

    log::debug!("Current svd2rust config: {:#?}", config);

    // Read SVD content
    let mut input_content = String::new();
    if let Some(input_path) = &config.input {
        let mut file = match File::open(input_path) {
