            }
        },
        Err(e) => {
            eprintln!("[ERROR svd2rust] Error parsing SVD XML file");
            eprintln!("    ");
            eprintln!("    Caused by:");
            eprintln!("        {}", e);
            process::exit(1);
        }
    };

    let result = render_device(&device, &config);

    let out_dir = config.output_dir.clone().unwrap_or_else(|| PathBuf::from("."));

    if let Err(e) = std::fs::create_dir_all(&out_dir) {
        eprintln!("[ERROR svd2rust] Error rendering device");
        eprintln!("    ");
        eprintln!("    Caused by:");
        eprintln!("        {}", e);
        process::exit(1);
    }

    let main_file_path = out_dir.join(&result.main_file_name);
    if let Err(e) = std::fs::write(&main_file_path, &result.main_file_content) {
        eprintln!("[ERROR svd2rust] Error rendering device");
        eprintln!("    ");
        eprintln!("    Caused by:");
        eprintln!("        {}", e);
        process::exit(1);
    }

    if let Some(generic_content) = &result.generic_file_content {
        let generic_path = out_dir.join("generic.rs");
        if let Err(e) = std::fs::write(&generic_path, generic_content) {
            eprintln!("[ERROR svd2rust] Error rendering device");
            eprintln!("    ");
            eprintln!("    Caused by:");
            eprintln!("        {}", e);
            process::exit(1);
        }
    }

    if let Some(dev_x_content) = &result.device_x_content {
        let dev_x_path = out_dir.join("device.x");
        if let Err(e) = std::fs::write(&dev_x_path, dev_x_content) {
            eprintln!("[ERROR svd2rust] Error rendering device");
            eprintln!("    ");
            eprintln!("    Caused by:");
            eprintln!("        {}", e);
            process::exit(1);
        }
    }

    if let Some(build_rs_content) = &result.build_rs_content {
        let build_rs_path = out_dir.join("build.rs");
        if let Err(e) = std::fs::write(&build_rs_path, build_rs_content) {
            eprintln!("[ERROR svd2rust] Error rendering device");
            eprintln!("    ");
            eprintln!("    Caused by:");
            eprintln!("        {}", e);
            process::exit(1);
        }
    }
}

fn parse_number(s: &str) -> Result<u64, std::num::ParseIntError> {
    let s = s.trim().replace('_', "");
    if let Some(stripped) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(stripped, 16)
    } else if let Some(stripped) = s.strip_prefix("0b").or_else(|| s.strip_prefix("0B")) {
        u64::from_str_radix(stripped, 2)
    } else if let Some(stripped) = s.strip_prefix('#') {
        u64::from_str_radix(stripped, 2)
    } else {
        s.parse::<u64>()
    }
}
