cat << 'EOF' > src/svd.rs
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct XmlNode {
    pub name: String,
    pub attributes: HashMap<String, String>,
    pub children: Vec<XmlNode>,
    pub text: String,
}

impl XmlNode {
    pub fn parse(s: &str) -> Result<XmlNode, String> {
        let bytes = s.as_bytes();
        let mut pos = 0;

        fn skip_ws_and_comments(bytes: &[u8], mut pos: usize) -> usize {
            loop {
                while pos < bytes.len()
                    && (bytes[pos] == b' '
                        || bytes[pos] == b'\t'
                        || bytes[pos] == b'\n'
                        || bytes[pos] == b'\r')
                {
                    pos += 1;
                }
                if pos + 4 <= bytes.len() && &bytes[pos..pos + 4] == b"<!--" {
                    pos += 4;
                    while pos + 3 <= bytes.len() && &bytes[pos..pos + 3] != b"-->" {
                        pos += 1;
                    }
                    pos += 3;
                } else if pos + 2 <= bytes.len() && &bytes[pos..pos + 2] == b"<?" {
                    pos += 2;
                    while pos + 2 <= bytes.len() && &bytes[pos..pos + 2] != b"?>" {
                        pos += 1;
                    }
                    pos += 2;
                } else {
                    break;
                }
            }
            pos
        }

        fn parse_node(bytes: &[u8], pos: &mut usize) -> Result<XmlNode, String> {
            *pos = skip_ws_and_comments(bytes, *pos);
            if *pos >= bytes.len() || bytes[*pos] != b'<' {
                return Err("the document does not have a root node".to_string());
            }
            *pos += 1;

            let name_start = *pos;
            while *pos < bytes.len()
                && !bytes[*pos].is_ascii_whitespace()
                && bytes[*pos] != b'>'
                && bytes[*pos] != b'/'
            {
                *pos += 1;
            }
            let name = std::str::from_utf8(&bytes[name_start..*pos])
                .map_err(|e| e.to_string())?
                .to_string();

            let mut attributes = HashMap::new();
            loop {
                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                if *pos >= bytes.len() || bytes[*pos] == b'>' || bytes[*pos] == b'/' {
                    break;
                }
                let attr_key_start = *pos;
                while *pos < bytes.len()
                    && !bytes[*pos].is_ascii_whitespace()
                    && bytes[*pos] != b'='
                    && bytes[*pos] != b'>'
                    && bytes[*pos] != b'/'
                {
                    *pos += 1;
                }
                let attr_key = std::str::from_utf8(&bytes[attr_key_start..*pos])
                    .map_err(|e| e.to_string())?
                    .to_string();

                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                let mut attr_val = String::new();
                if *pos < bytes.len() && bytes[*pos] == b'=' {
                    *pos += 1;
                    while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                        *pos += 1;
                    }
                    if *pos < bytes.len() && (bytes[*pos] == b'"' || bytes[*pos] == b'\'') {
                        let quote = bytes[*pos];
                        *pos += 1;
                        let val_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != quote {
                            *pos += 1;
                        }
                        attr_val = std::str::from_utf8(&bytes[val_start..*pos])
                            .map_err(|e| e.to_string())?
                            .to_string();
                        if *pos < bytes.len() {
                            *pos += 1;
                        }
                    }
                }
                attributes.insert(attr_key, attr_val);
            }

            if *pos < bytes.len() && bytes[*pos] == b'/' {
                *pos += 1;
                if *pos < bytes.len() && bytes[*pos] == b'>' {
                    *pos += 1;
                }
                return Ok(XmlNode {
                    name,
                    attributes,
                    children: vec![],
                    text: String::new(),
                });
            }

            if *pos < bytes.len() && bytes[*pos] == b'>' {
                *pos += 1;
            }

            let mut children = vec![];
            let mut text = String::new();

            loop {
                *pos = skip_ws_and_comments(bytes, *pos);
                if *pos >= bytes.len() {
                    break;
                }

                if bytes[*pos] == b'<' {
                    if *pos + 1 < bytes.len() && bytes[*pos + 1] == b'/' {
                        *pos += 2;
                        let tag_close_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != b'>' {
                            *pos += 1;
                        }
                        let close_name = std::str::from_utf8(&bytes[tag_close_start..*pos])
                            .unwrap_or("")
                            .trim();
                        if close_name != name {
                            return Err(format!("expected '{}' tag, not '{}'", name, close_name));
                        }
                        if *pos < bytes.len() {
                            *pos += 1;
                        }
                        break;
                    } else {
                        children.push(parse_node(bytes, pos)?);
                    }
                } else {
                    let text_start = *pos;
                    while *pos < bytes.len() && bytes[*pos] != b'<' {
                        *pos += 1;
                    }
                    let t = std::str::from_utf8(&bytes[text_start..*pos])
                        .unwrap_or("")
                        .trim();
                    if !t.is_empty() {
                        if !text.is_empty() {
                            text.push(' ');
                        }
                        text.push_str(t);
                    }
                }
            }

            Ok(XmlNode {
                name,
                attributes,
                children,
                text,
            })
        }

        pos = skip_ws_and_comments(bytes, pos);
        let node = parse_node(bytes, &mut pos)?;
        if node.name != "device" {
            return Err(format!("expected 'device' tag, not '{}'", node.name));
        }
        Ok(node)
    }

    pub fn child_text(&self, name: &str) -> Option<String> {
        self.children
            .iter()
            .find(|c| c.name == name)
            .map(|c| c.text.clone())
    }

    pub fn children_named<'a>(&'a self, name: &'a str) -> impl Iterator<Item = &'a XmlNode> {
        self.children.iter().filter(move |c| c.name == name)
    }

    pub fn attr(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|s| s.as_str())
    }
}

pub fn parse_svd_number(s: &str) -> Result<u64, String> {
    let s = s.trim().replace('_', "");
    if let Some(stripped) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(stripped, 16).map_err(|e| e.to_string())
    } else if let Some(stripped) = s.strip_prefix("0b").or_else(|| s.strip_prefix("0B")) {
        u64::from_str_radix(stripped, 2).map_err(|e| e.to_string())
    } else if let Some(stripped) = s.strip_prefix('#') {
        u64::from_str_radix(stripped, 2).map_err(|e| e.to_string())
    } else {
        s.parse::<u64>().map_err(|e| e.to_string())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Access {
    ReadOnly,
    WriteOnly,
    ReadWrite,
    WriteOnce,
    ReadWriteOnce,
}

impl Access {
    pub fn parse(s: &str) -> Option<Self> {
        match s.trim() {
            "read-only" => Some(Access::ReadOnly),
            "write-only" => Some(Access::WriteOnly),
            "read-write" => Some(Access::ReadWrite),
            "writeOnce" => Some(Access::WriteOnce),
            "read-writeOnce" => Some(Access::ReadWriteOnce),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Device {
    pub name: String,
    pub peripherals: Vec<Peripheral>,
}

#[derive(Debug, Clone)]
pub struct Peripheral {
    pub name: String,
    pub description: Option<String>,
    pub base_address: u64,
    pub derived_from: Option<String>,
    pub interrupts: Vec<Interrupt>,
    pub registers: Vec<RegisterCluster>,
}

#[derive(Debug, Clone)]
pub struct Interrupt {
    pub name: String,
    pub description: Option<String>,
    pub value: u16,
}

#[derive(Debug, Clone)]
pub enum RegisterCluster {
    Register(Register),
    Cluster(Cluster),
}

#[derive(Debug, Clone)]
pub struct DimElement {
    pub dim: u32,
    pub dim_increment: u64,
    pub dim_index: Option<Vec<String>>,
}

impl DimElement {
    pub fn parse(node: &XmlNode) -> Option<Self> {
        let dim_str = node.child_text("dim")?;
        let dim = dim_str.trim().parse::<u32>().ok()?;
        let inc_str = node.child_text("dimIncrement")?;
        let dim_increment = parse_svd_number(&inc_str).ok()?;
        let dim_index = node.child_text("dimIndex").map(|s| {
            if s.contains(',') {
                s.split(',').map(|x| x.trim().to_string()).collect()
            } else if let Some((start, end)) = s.split_once('-') {
                if let (Ok(s_num), Ok(e_num)) = (start.trim().parse::<u32>(), end.trim().parse::<u32>()) {
                    (s_num..=e_num).map(|n| n.to_string()).collect()
                } else {
                    vec![s]
                }
            } else {
                vec![s]
            }
        });
        Some(DimElement {
            dim,
            dim_increment,
            dim_index,
        })
    }
}

#[derive(Debug, Clone)]
pub struct Register {
    pub name: String,
    pub description: Option<String>,
    pub address_offset: u64,
    pub size: Option<u32>,
    pub access: Option<Access>,
    pub reset_value: Option<u64>,
    pub dim: Option<DimElement>,
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone)]
pub struct Cluster {
    pub name: String,
    pub description: Option<String>,
    pub address_offset: u64,
    pub dim: Option<DimElement>,
}

#[derive(Debug, Clone)]
pub struct Field {
    pub name: String,
    pub description: Option<String>,
    pub bit_offset: u32,
    pub bit_width: u32,
    pub access: Option<Access>,
    pub enumerated_values: Vec<EnumeratedValues>,
}

#[derive(Debug, Clone)]
pub struct EnumeratedValues {
    pub name: Option<String>,
    pub values: Vec<EnumeratedValue>,
}

#[derive(Debug, Clone)]
pub struct EnumeratedValue {
    pub name: String,
    pub description: Option<String>,
    pub value: Option<u64>,
}

impl Device {
    pub fn from_xml(root: &XmlNode) -> Result<Device, String> {
        let name = root.child_text("name").ok_or("missing 'name'")?;

        let mut peripherals = vec![];
        if let Some(periphs_node) = root.children.iter().find(|c| c.name == "peripherals") {
            for p_node in periphs_node.children_named("peripheral") {
                peripherals.push(Peripheral::from_xml(p_node)?);
            }
        }

        Ok(Device {
            name,
            peripherals,
        })
    }
}

impl Peripheral {
    pub fn from_xml(node: &XmlNode) -> Result<Peripheral, String> {
        let name = node.child_text("name").ok_or("peripheral missing name")?;
        let description = node.child_text("description");
        let base_address = node
            .child_text("baseAddress")
            .and_then(|s| parse_svd_number(&s).ok())
            .unwrap_or(0);
        let derived_from = node
            .attr("derivedFrom")
            .map(|s| s.to_string())
            .or_else(|| node.child_text("derivedFrom"));

        let mut interrupts = vec![];
        for int_node in node.children_named("interrupt") {
            let int_name = int_node.child_text("name").unwrap_or_default();
            let int_desc = int_node.child_text("description");
            let int_val = int_node
                .child_text("value")
                .and_then(|s| s.parse::<u16>().ok())
                .unwrap_or(0);
            interrupts.push(Interrupt {
                name: int_name,
                description: int_desc,
                value: int_val,
            });
        }

        let mut registers = vec![];
        if let Some(regs_node) = node.children.iter().find(|c| c.name == "registers") {
            for child in &regs_node.children {
                if child.name == "register" {
                    registers.push(RegisterCluster::Register(Register::from_xml(child)?));
                } else if child.name == "cluster" {
                    registers.push(RegisterCluster::Cluster(Cluster::from_xml(child)?));
                }
            }
        }

        Ok(Peripheral {
            name,
            description,
            base_address,
            derived_from,
            interrupts,
            registers,
        })
    }
}

impl Register {
    pub fn from_xml(node: &XmlNode) -> Result<Register, String> {
        let name = node.child_text("name").ok_or("register missing name")?;
        let description = node.child_text("description");
        let address_offset = node
            .child_text("addressOffset")
            .and_then(|s| parse_svd_number(&s).ok())
            .unwrap_or(0);
        let size = node.child_text("size").and_then(|s| parse_svd_number(&s).ok()).map(|n| n as u32);
        let access = node.child_text("access").and_then(|s| Access::parse(&s));
        let reset_value = node.child_text("resetValue").and_then(|s| parse_svd_number(&s).ok());
        let dim = DimElement::parse(node);

        let mut fields = vec![];
        if let Some(fields_node) = node.children.iter().find(|c| c.name == "fields") {
            for f_node in fields_node.children_named("field") {
                fields.push(Field::from_xml(f_node)?);
            }
        }

        Ok(Register {
            name,
            description,
            address_offset,
            size,
            access,
            reset_value,
            dim,
            fields,
        })
    }
}

impl Cluster {
    pub fn from_xml(node: &XmlNode) -> Result<Cluster, String> {
        let name = node.child_text("name").ok_or("cluster missing name")?;
        let description = node.child_text("description");
        let address_offset = node
            .child_text("addressOffset")
            .and_then(|s| parse_svd_number(&s).ok())
            .unwrap_or(0);
        let dim = DimElement::parse(node);

        Ok(Cluster {
            name,
            description,
            address_offset,
            dim,
        })
    }
}

impl Field {
    pub fn from_xml(node: &XmlNode) -> Result<Field, String> {
        let name = node.child_text("name").ok_or("field missing name")?;
        let description = node.child_text("description");
        let access = node.child_text("access").and_then(|s| Access::parse(&s));

        let mut bit_offset = 0;
        let mut bit_width = 1;

        if let (Some(bo), Some(bw)) = (node.child_text("bitOffset"), node.child_text("bitWidth")) {
            bit_offset = parse_svd_number(&bo).unwrap_or(0) as u32;
            bit_width = parse_svd_number(&bw).unwrap_or(1) as u32;
        } else if let Some(br) = node.child_text("bitRange") {
            let br = br.trim_matches(|c| c == '[' || c == ']');
            if let Some((msb, lsb)) = br.split_once(':') {
                let msb_val = parse_svd_number(msb).unwrap_or(0) as u32;
                let lsb_val = parse_svd_number(lsb).unwrap_or(0) as u32;
                bit_offset = lsb_val;
                bit_width = msb_val.saturating_sub(lsb_val) + 1;
            }
        } else if let (Some(lsb), Some(msb)) = (node.child_text("lsb"), node.child_text("msb")) {
            let lsb_val = parse_svd_number(&lsb).unwrap_or(0) as u32;
            let msb_val = parse_svd_number(&msb).unwrap_or(0) as u32;
            bit_offset = lsb_val;
            bit_width = msb_val.saturating_sub(lsb_val) + 1;
        }

        let mut enumerated_values = vec![];
        for evs_node in node.children_named("enumeratedValues") {
            enumerated_values.push(EnumeratedValues::from_xml(evs_node)?);
        }

        Ok(Field {
            name,
            description,
            bit_offset,
            bit_width,
            access,
            enumerated_values,
        })
    }
}

impl EnumeratedValues {
    pub fn from_xml(node: &XmlNode) -> Result<EnumeratedValues, String> {
        let name = node.child_text("name");

        let mut values = vec![];
        for ev_node in node.children_named("enumeratedValue") {
            let name = ev_node.child_text("name").unwrap_or_default();
            let description = ev_node.child_text("description");
            let value = ev_node.child_text("value").and_then(|s| parse_svd_number(&s).ok());
            values.push(EnumeratedValue {
                name,
                description,
                value,
            });
        }

        Ok(EnumeratedValues {
            name,
            values,
        })
    }
}
EOF

./compile.sh
"}

actions.command:
cat << 'EOF' > src/generate/device.rs
use proc_macro2::TokenStream;
use quote::quote;
use crate::config::{Config, Target};
use crate::svd::{Device, Interrupt};
use crate::generate::util::{format_ident, make_ident};
use crate::generate::peripheral::render_peripheral;
use crate::generate::generic;

pub struct DeviceRenderResult {
    pub main_file_name: String,
    pub main_file_content: String,
    pub generic_file_content: Option<String>,
    pub device_x_content: Option<String>,
    pub build_rs_content: Option<String>,
}

pub fn render_device(device: &Device, config: &Config) -> DeviceRenderResult {
    log::info!("Rendering device");

    let device_name = &device.name;

    let mut interrupts = vec![];
    for p in &device.peripherals {
        for int in &p.interrupts {
            interrupts.push(int.clone());
        }
    }
    interrupts.sort_by_key(|i| i.value);
    interrupts.dedup_by_key(|i| i.value);

    let doc_comment = format!(
        "Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust",
        device_name.to_uppercase()
    );

    let crate_attrs = if !config.skip_crate_attributes && !config.make_mod {
        quote! {
            #![doc = #doc_comment]
            #![allow(non_camel_case_types)]
            #![allow(non_snake_case)]
            #![no_std]
            #![cfg_attr(docsrs, feature(doc_cfg))]
        }
    } else if !config.skip_crate_attributes && config.make_mod {
        quote! {
            #![doc = #doc_comment]
        }
    } else {
        quote! {}
    };

    let (generic_import, generic_file_content) = if config.generic_mod {
        let generic_ts = generic::render(config);
        (
            quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc = "Common register and bit access and modify traits"]
                pub mod generic;
            },
            Some(generic_ts.to_string()),
        )
    } else {
        let generic_ts = generic::render(config);
        (
            quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc = "Common register and bit access and modify traits"]
                pub mod generic {
                    #generic_ts
                }
            },
            None,
        )
    };

    let mut periph_fields = quote! {};
    let mut periph_inits = quote! {};
    let mut periph_mods = quote! {};

    for p in &device.peripherals {
        let raw_p_name = &p.name;
        let field_name = format_ident(raw_p_name, "peripheral_singleton", config);
        let field_ident = make_ident(&field_name);

        let type_name = format_ident(raw_p_name, "peripheral", config);
        let type_ident = make_ident(&type_name);

        let p_doc = p.description.as_deref().unwrap_or(raw_p_name);

        periph_fields.extend(quote! {
            #[doc = #p_doc]
            pub #field_ident: #type_ident,
        });

        periph_inits.extend(quote! {
            #field_ident: #type_ident::steal(),
        });

        periph_mods.extend(render_peripheral(p, config));
    }

    let peripherals_struct = quote! {
        #[no_mangle]
        static mut DEVICE_PERIPHERALS: bool = false;

        #[doc = " All the peripherals."]
        #[allow(non_snake_case)]
        pub struct Peripherals {
            #periph_fields
        }

        impl Peripherals {
            #[doc = " Returns all the peripherals *once*."]
            #[cfg(feature = "critical-section")]
            #[inline]
            pub fn take() -> Option<Self> {
                critical_section::with(|_| {
                    if unsafe { DEVICE_PERIPHERALS } {
                        return None;
                    }
                    Some(unsafe { Peripherals::steal() })
                })
            }

            #[doc = " Unchecked version of `Peripherals::take`."]
            #[doc = ""]
            #[doc = " # Safety"]
            #[doc = ""]
            #[doc = " Each of the returned peripherals must be used at most once."]
            #[inline]
            pub unsafe fn steal() -> Self {
                DEVICE_PERIPHERALS = true;
                Peripherals {
                    #periph_inits
                }
            }
        }
    };

    let interrupt_code = render_interrupts(&interrupts, config);

    let main_ts = quote! {
        #crate_attrs
        #generic_import
        #interrupt_code
        #periph_mods
        #peripherals_struct
    };

    let main_file_name = if config.make_mod {
        "mod.rs".to_string()
    } else {
        "lib.rs".to_string()
    };

    let (device_x_content, build_rs_content) = if matches!(
        config.target,
        Target::CortexM | Target::Msp430 | Target::RISCV | Target::XtensaLX
    ) {
        let mut dev_x = String::new();
        for int in &interrupts {
            let int_name = format_ident(&int.name, "interrupt", config);
            dev_x.push_str(&format!("PROVIDE({} = DefaultHandler);\n", int_name));
        }

        let build_rs_ts = quote! {
            #![doc = r" Builder file for Peripheral access crate generated by svd2rust tool"]
            use std::env;
            use std::fs::File;
            use std::io::Write;
            use std::path::PathBuf;

            fn main() {
                if env::var_os("CARGO_FEATURE_RT").is_some() {
                    let out = &PathBuf::from(env::var_os("OUT_DIR").unwrap());
                    File::create(out.join("device.x"))
                        .unwrap()
                        .write_all(include_bytes!("device.x"))
                        .unwrap();
                    println!("cargo:rustc-link-search={}", out.display());
                    println!("cargo:rerun-if-changed=device.x");
                }
                println!("cargo:rerun-if-changed=build.rs");
            }
        };

        (Some(dev_x), Some(build_rs_ts.to_string()))
    } else {
        (None, None)
    };

    DeviceRenderResult {
        main_file_name,
        main_file_content: main_ts.to_string(),
        generic_file_content,
        device_x_content,
        build_rs_content,
    }
}

fn render_interrupts(interrupts: &[Interrupt], config: &Config) -> TokenStream {
    if interrupts.is_empty() {
        if config.target == Target::CortexM {
            return quote! {
                #[cfg(feature = "rt")]
                extern "C" {}

                #[doc(hidden)]
                #[repr(C)]
                pub union Vector {
                    _handler: unsafe extern "C" fn(),
                    _reserved: u32,
                }

                #[cfg(feature = "rt")]
                #[doc(hidden)]
                #[link_section = ".vector_table.interrupts"]
                #[no_mangle]
                pub static __INTERRUPTS: [Vector; 0] = [];

                #[doc = "Enumeration of all the interrupts."]
                #[derive(Copy, Clone, Debug, PartialEq, Eq)]
                pub enum Interrupt {}

                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 {
                        match self {}
                    }
                }
            };
        } else {
            return quote! {};
        }
    }

    let mut variants = quote! {};
    let mut try_from_arms = quote! {};

    for int in interrupts {
        let int_name = format_ident(&int.name, "interrupt", config);
        let int_ident = make_ident(&int_name);
        let val_lit = proc_macro2::Literal::u16_unsuffixed(int.value);
        let doc = format!("{} - {}", int.value, int.description.as_deref().unwrap_or(""));

        variants.extend(quote! {
            #[doc = #doc]
            #int_ident = #val_lit,
        });

        try_from_arms.extend(quote! {
            #val_lit => Ok(Interrupt::#int_ident),
        });
    }

    match config.target {
        Target::CortexM => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }

                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 {
                        self as u16
                    }
                }
            }
        }
        Target::None => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }

                #[doc = r" TryFromInterruptError"]
                #[derive(Debug, Copy, Clone)]
                pub struct TryFromInterruptError(());

                impl Interrupt {
                    #[doc = r" Attempt to convert a given value into an `Interrupt`"]
                    #[inline]
                    pub fn try_from(value: u8) -> Result<Self, TryFromInterruptError> {
                        match value {
                            #try_from_arms
                            _ => Err(TryFromInterruptError(())),
                        }
                    }
                }

                pub use self::interrupt::Interrupt;
            }
        }
        _ => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }
            }
        }
    }
}
EOF

cat << 'EOF' > src/generate/peripheral.rs
use proc_macro2::TokenStream;
use quote::quote;
use crate::config::Config;
use crate::svd::{Peripheral, RegisterCluster};
use crate::generate::util::{format_ident, make_ident};
use crate::generate::register::render_register;

pub fn render_peripheral(
    peripheral: &Peripheral,
    config: &Config,
) -> TokenStream {
    let raw_periph_name = &peripheral.name;
    let periph_mod_name = format_ident(raw_periph_name, "peripheral_mod", config);
    let periph_mod_ident = make_ident(&periph_mod_name);

    let periph_type_name = format_ident(raw_periph_name, "peripheral", config);
    let periph_type_ident = make_ident(&periph_type_name);

    let periph_spec_name = format_ident(raw_periph_name, "peripheral_spec", config);
    let periph_spec_ident = make_ident(&periph_spec_name);

    let periph_doc = peripheral.description.as_deref().unwrap_or(raw_periph_name);
    let base_addr = (peripheral.base_address + config.base_address_shift) as usize;
    let base_addr_lit = proc_macro2::Literal::usize_unsuffixed(base_addr);

    if let Some(derived_from) = &peripheral.derived_from {
        let derived_mod_name = format_ident(derived_from, "peripheral_mod", config);
        let derived_mod_ident = make_ident(&derived_mod_name);

        return quote! {
            #[doc = #periph_doc]
            pub type #periph_type_ident = crate::Periph<#periph_spec_ident>;

            pub struct #periph_spec_ident;

            impl crate::PeripheralSpec for #periph_spec_ident {
                type RB = #derived_mod_ident :: RegisterBlock;
                const ADDRESS: usize = #base_addr_lit;
                const NAME: &'static str = #raw_periph_name;
            }

            #[doc = #periph_doc]
            pub use self :: #derived_mod_ident as #periph_mod_ident;
        };
    }

    let mut items = peripheral.registers.clone();
    items.sort_by_key(|rc| match rc {
        RegisterCluster::Register(r) => r.address_offset,
        RegisterCluster::Cluster(c) => c.address_offset,
    });

    let mut rb_fields = quote! {};
    let mut rb_methods = quote! {};
    let mut reg_typedefs = quote! {};
    let mut reg_mods = quote! {};

    let mut current_offset: u64 = 0;
    let mut reserved_count = 1;

    for rc in &items {
        match rc {
            RegisterCluster::Register(reg) => {
                let offset = reg.address_offset;
                let size_bytes = (reg.size.unwrap_or(32) / 8) as u64;

                if offset > current_offset {
                    let gap = offset - current_offset;
                    let gap_lit = proc_macro2::Literal::u64_unsuffixed(gap);
                    let res_ident = make_ident(&format!("_reserved{}", reserved_count));
                    reserved_count += 1;
                    rb_fields.extend(quote! {
                        #res_ident: [u8; #gap_lit],
                    });
                    current_offset = offset;
                }

                let reg_res = render_register(reg, config);
                reg_typedefs.extend(reg_res.accessor_typedef);
                reg_mods.extend(reg_res.register_mod);

                let clean_reg_name = reg.name.replace("[%s]", "").replace("%s", "");
                let field_ident_name = format_ident(&clean_reg_name, "register_accessor", config);
                let field_ident = make_ident(&field_ident_name);

                let accessor_type_name = format_ident(&clean_reg_name, "register", config);
                let accessor_type_ident = make_ident(&accessor_type_name);

                let method_name = format_ident(&clean_reg_name, "register_accessor", config);
                let method_ident = make_ident(&method_name);
                let reg_doc = reg.description.as_deref().unwrap_or(&clean_reg_name);

                if let Some(dim) = &reg.dim {
                    let count = dim.dim as usize;
                    let count_lit = proc_macro2::Literal::usize_unsuffixed(count);

                    if let Some(dim_indices) = &dim.dim_index {
                        if dim_indices.len() == count && dim_indices.iter().any(|idx| idx.parse::<usize>().is_err()) {
                            rb_fields.extend(quote! {
                                #field_ident: [#accessor_type_ident; #count_lit],
                            });

                            let iter_method_name = format_ident(&format!("{}_iter", clean_reg_name), "register_accessor", config);
                            let iter_method_ident = make_ident(&iter_method_name);

                            rb_methods.extend(quote! {
                                #[doc = #reg_doc]
                                #[inline(always)]
                                pub const fn #field_ident(&self, n: usize) -> &#accessor_type_ident {
                                    &self.#field_ident[n]
                                }

                                #[doc = "Iterator for array of:"]
                                #[doc = #reg_doc]
                                #[inline(always)]
                                pub fn #iter_method_ident(&self) -> impl Iterator<Item = &#accessor_type_ident> {
                                    self.#field_ident.iter()
                                }
                            });

                            for (idx_n, idx_str) in dim_indices.iter().enumerate() {
                                let sub_method_raw = reg.name.replace("[%s]", idx_str).replace("%s", idx_str);
                                let sub_method_name = format_ident(&sub_method_raw, "register_accessor", config);
                                let sub_method_ident = make_ident(&sub_method_name);
                                let idx_lit = proc_macro2::Literal::usize_unsuffixed(idx_n);

                                rb_methods.extend(quote! {
                                    #[doc = #reg_doc]
                                    #[inline(always)]
                                    pub const fn #sub_method_ident(&self) -> &#accessor_type_ident {
                                        self.#field_ident(#idx_lit)
                                    }
                                });
                            }

                            current_offset += count as u64 * dim.dim_increment;
                            continue;
                        }
                    }

                    rb_fields.extend(quote! {
                        #field_ident: [#accessor_type_ident; #count_lit],
                    });

                    let iter_method_name = format_ident(&format!("{}_iter", clean_reg_name), "register_accessor", config);
                    let iter_method_ident = make_ident(&iter_method_name);

                    rb_methods.extend(quote! {
                        #[doc = #reg_doc]
                        #[inline(always)]
                        pub const fn #method_ident(&self, n: usize) -> &#accessor_type_ident {
                            &self.#field_ident[n]
                        }

                        #[doc = "Iterator for array of:"]
                        #[doc = #reg_doc]
                        #[inline(always)]
                        pub fn #iter_method_ident(&self) -> impl Iterator<Item = &#accessor_type_ident> {
                            self.#field_ident.iter()
                        }
                    });

                    current_offset += count as u64 * dim.dim_increment;
                } else {
                    rb_fields.extend(quote! {
                        #field_ident: #accessor_type_ident,
                    });

                    rb_methods.extend(quote! {
                        #[doc = #reg_doc]
                        #[inline(always)]
                        pub const fn #method_ident(&self) -> &#accessor_type_ident {
                            &self.#field_ident
                        }
                    });

                    current_offset += size_bytes;
                }
            }
            RegisterCluster::Cluster(cluster) => {
                let offset = cluster.address_offset;
                if offset > current_offset {
                    let gap = offset - current_offset;
                    let gap_lit = proc_macro2::Literal::u64_unsuffixed(gap);
                    let res_ident = make_ident(&format!("_reserved{}", reserved_count));
                    reserved_count += 1;
                    rb_fields.extend(quote! {
                        #res_ident: [u8; #gap_lit],
                    });
                    current_offset = offset;
                }

                let clean_cluster_name = cluster.name.replace("[%s]", "").replace("%s", "");
                let cluster_field_name = format_ident(&clean_cluster_name, "cluster_accessor", config);
                let cluster_field_ident = make_ident(&cluster_field_name);

                let cluster_mod_name = format_ident(&clean_cluster_name, "cluster_mod", config);
                let cluster_mod_ident = make_ident(&cluster_mod_name);

                let cluster_type_name = format_ident(&clean_cluster_name, "cluster", config);
                let cluster_type_ident = make_ident(&cluster_type_name);

                let cluster_doc = cluster.description.as_deref().unwrap_or(&clean_cluster_name);

                if let Some(dim) = &cluster.dim {
                    let count = dim.dim as usize;
                    let count_lit = proc_macro2::Literal::usize_unsuffixed(count);
                    let inc = dim.dim_increment;
                    let inc_lit = proc_macro2::Literal::u64_unsuffixed(inc);

                    rb_fields.extend(quote! {
                        #cluster_field_ident: (),
                    });

                    let iter_method_name = format_ident(&format!("{}_iter", clean_cluster_name), "cluster_accessor", config);
                    let iter_method_ident = make_ident(&iter_method_name);

                    rb_methods.extend(quote! {
                        #[doc = #cluster_doc]
                        #[inline(always)]
                        pub const fn #cluster_field_ident(&self, n: usize) -> &#cluster_mod_ident :: #cluster_type_ident {
                            #[allow(clippy::no_effect)]
                            [(); #count_lit][n];
                            unsafe {
                                &*core::ptr::from_ref(self)
                                    .cast::<u8>()
                                    .add(#inc_lit as usize * n)
                                    .cast()
                            }
                        }

                        #[doc = "Iterator for array of:"]
                        #[doc = #cluster_doc]
                        #[inline(always)]
                        pub fn #iter_method_ident(&self) -> impl Iterator<Item = &#cluster_mod_ident :: #cluster_type_ident> {
                            (0..#count_lit).map(move |n| unsafe {
                                &*core::ptr::from_ref(self)
                                    .cast::<u8>()
                                    .add(#inc_lit as usize * n)
                                    .cast()
                            })
                        }
                    });

                    current_offset += count as u64 * inc;
                } else {
                    rb_fields.extend(quote! {
                        #cluster_field_ident: #cluster_mod_ident :: #cluster_type_ident,
                    });

                    rb_methods.extend(quote! {
                        #[doc = #cluster_doc]
                        #[inline(always)]
                        pub const fn #cluster_field_ident(&self) -> &#cluster_mod_ident :: #cluster_type_ident {
                            &self.#cluster_field_ident
                        }
                    });
                }
            }
        }
    }

    quote! {
        #[doc = #periph_doc]
        pub type #periph_type_ident = crate::Periph<#periph_spec_ident>;

        pub struct #periph_spec_ident;

        impl crate::PeripheralSpec for #periph_spec_ident {
            type RB = #periph_mod_ident :: RegisterBlock;
            const ADDRESS: usize = #base_addr_lit;
            const NAME: &'static str = #raw_periph_name;
        }

        #[doc = #periph_doc]
        pub mod #periph_mod_ident {
            #[repr(C)]
            #[doc = "Register block"]
            pub struct RegisterBlock {
                #rb_fields
            }

            impl RegisterBlock {
                #rb_methods
            }

            #reg_typedefs
            #reg_mods
        }
    }
}
