use proc_macro2::TokenStream;
use quote::quote;
use crate::config::{Config, Target};
use crate::svd::{Device, Interrupt};
use crate::generate::util::{format_ident, make_ident};
use crate::generate::peripheral::render_peripheral;
use crate::generate::generic;

pub struct DeviceRenderResult {
    pub main_file_name: String,
    pub main_file_content: String,
    pub generic_file_content: Option<String>,
    pub device_x_content: Option<String>,
    pub build_rs_content: Option<String>,
}

pub fn render_device(device: &Device, config: &Config) -> DeviceRenderResult {
    log::info!("Rendering device");

    let device_name = &device.name;

    let mut interrupts = vec![];
    for p in &device.peripherals {
        for int in &p.interrupts {
            interrupts.push(int.clone());
        }
    }
    interrupts.sort_by_key(|i| i.value);
    interrupts.dedup_by_key(|i| i.value);

    let doc_comment = format!(
        "Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust",
        device_name.to_uppercase()
    );

    let crate_attrs = if !config.skip_crate_attributes && !config.make_mod {
        quote! {
            #![doc = #doc_comment]
            #![allow(non_camel_case_types)]
            #![allow(non_snake_case)]
            #![no_std]
            #![cfg_attr(docsrs, feature(doc_cfg))]
        }
    } else if !config.skip_crate_attributes && config.make_mod {
        quote! {
            #![doc = #doc_comment]
        }
    } else {
        quote! {}
    };

    let (generic_import, generic_file_content) = if config.generic_mod {
        let generic_ts = generic::render(config);
        (
            quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc = "Common register and bit access and modify traits"]
                pub mod generic;
            },
            Some(generic_ts.to_string()),
        )
    } else {
        let generic_ts = generic::render(config);
        (
            quote! {
                #[allow(unused_imports)]
                use generic::*;
                #[doc = "Common register and bit access and modify traits"]
                pub mod generic {
                    #generic_ts
                }
            },
            None,
        )
    };

    let mut periph_fields = quote! {};
    let mut periph_inits = quote! {};
    let mut periph_mods = quote! {};

    for p in &device.peripherals {
        let raw_p_name = &p.name;
        let field_name = format_ident(raw_p_name, "peripheral_singleton", config);
        let field_ident = make_ident(&field_name);

        let type_name = format_ident(raw_p_name, "peripheral", config);
        let type_ident = make_ident(&type_name);

        let p_doc = p.description.as_deref().unwrap_or(raw_p_name);

        periph_fields.extend(quote! {
            #[doc = #p_doc]
            pub #field_ident: #type_ident,
        });

        periph_inits.extend(quote! {
            #field_ident: #type_ident::steal(),
        });

        periph_mods.extend(render_peripheral(p, config));
    }

    let peripherals_struct = quote! {
        #[no_mangle]
        static mut DEVICE_PERIPHERALS: bool = false;

        #[doc = " All the peripherals."]
        #[allow(non_snake_case)]
        pub struct Peripherals {
            #periph_fields
        }

        impl Peripherals {
            #[doc = " Returns all the peripherals *once*."]
            #[cfg(feature = "critical-section")]
            #[inline]
            pub fn take() -> Option<Self> {
                critical_section::with(|_| {
                    if unsafe { DEVICE_PERIPHERALS } {
                        return None;
                    }
                    Some(unsafe { Peripherals::steal() })
                })
            }

            #[doc = " Unchecked version of `Peripherals::take`."]
            #[doc = ""]
            #[doc = " # Safety"]
            #[doc = ""]
            #[doc = " Each of the returned peripherals must be used at most once."]
            #[inline]
            pub unsafe fn steal() -> Self {
                DEVICE_PERIPHERALS = true;
                Peripherals {
                    #periph_inits
                }
            }
        }
    };

    let interrupt_code = render_interrupts(&interrupts, config);

    let main_ts = quote! {
        #crate_attrs
        #generic_import
        #interrupt_code
        #periph_mods
        #peripherals_struct
    };

    let main_file_name = if config.make_mod {
        "mod.rs".to_string()
    } else {
        "lib.rs".to_string()
    };

    let (device_x_content, build_rs_content) = if matches!(
        config.target,
        Target::CortexM | Target::Msp430 | Target::RISCV | Target::XtensaLX
    ) {
        let mut dev_x = String::new();
        for int in &interrupts {
            let int_name = format_ident(&int.name, "interrupt", config);
            dev_x.push_str(&format!("PROVIDE({} = DefaultHandler);\n", int_name));
        }

        let build_rs_ts = quote! {
            #![doc = r" Builder file for Peripheral access crate generated by svd2rust tool"]
            use std::env;
            use std::fs::File;
            use std::io::Write;
            use std::path::PathBuf;

            fn main() {
                if env::var_os("CARGO_FEATURE_RT").is_some() {
                    let out = &PathBuf::from(env::var_os("OUT_DIR").unwrap());
                    File::create(out.join("device.x"))
                        .unwrap()
                        .write_all(include_bytes!("device.x"))
                        .unwrap();
                    println!("cargo:rustc-link-search={}", out.display());
                    println!("cargo:rerun-if-changed=device.x");
                }
                println!("cargo:rerun-if-changed=build.rs");
            }
        };

        (Some(dev_x), Some(build_rs_ts.to_string()))
    } else {
        (None, None)
    };

    DeviceRenderResult {
        main_file_name,
        main_file_content: main_ts.to_string(),
        generic_file_content,
        device_x_content,
        build_rs_content,
    }
}

fn render_interrupts(interrupts: &[Interrupt], config: &Config) -> TokenStream {
    if interrupts.is_empty() {
        if config.target == Target::CortexM {
            return quote! {
                #[cfg(feature = "rt")]
                extern "C" {}

                #[doc(hidden)]
                #[repr(C)]
                pub union Vector {
                    _handler: unsafe extern "C" fn(),
                    _reserved: u32,
                }

                #[cfg(feature = "rt")]
                #[doc(hidden)]
                #[link_section = ".vector_table.interrupts"]
                #[no_mangle]
                pub static __INTERRUPTS: [Vector; 0] = [];

                #[doc = "Enumeration of all the interrupts."]
                #[derive(Copy, Clone, Debug, PartialEq, Eq)]
                pub enum Interrupt {}

                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 {
                        match self {}
                    }
                }
            };
        } else {
            return quote! {};
        }
    }

    let mut variants = quote! {};
    let mut try_from_arms = quote! {};

    for int in interrupts {
        let int_name = format_ident(&int.name, "interrupt", config);
        let int_ident = make_ident(&int_name);
        let val_lit = proc_macro2::Literal::u16_unsuffixed(int.value);
        let doc = format!("{} - {}", int.value, int.description.as_deref().unwrap_or(""));

        variants.extend(quote! {
            #[doc = #doc]
            #int_ident = #val_lit,
        });

        try_from_arms.extend(quote! {
            #val_lit => Ok(Interrupt::#int_ident),
        });
    }

    match config.target {
        Target::CortexM => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }

                unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {
                    #[inline(always)]
                    fn number(self) -> u16 {
                        self as u16
                    }
                }
            }
        }
        Target::None => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }

                #[doc = r" TryFromInterruptError"]
                #[derive(Debug, Copy, Clone)]
                pub struct TryFromInterruptError(());

                impl Interrupt {
                    #[doc = r" Attempt to convert a given value into an `Interrupt`"]
                    #[inline]
                    pub fn try_from(value: u8) -> Result<Self, TryFromInterruptError> {
                        match value {
                            #try_from_arms
                            _ => Err(TryFromInterruptError(())),
                        }
                    }
                }

                pub use self::interrupt::Interrupt;
            }
        }
        _ => {
            quote! {
                #[repr(u16)]
                pub enum Interrupt {
                    #variants
                }
            }
        }
    }
}
