cat << 'EOF' > src/svd.rs
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct XmlNode {
    pub name: String,
    pub attributes: HashMap<String, String>,
    pub children: Vec<XmlNode>,
    pub text: String,
}

impl XmlNode {
    pub fn parse(s: &str) -> Result<XmlNode, String> {
        let bytes = s.as_bytes();
        let mut pos = 0;

        fn skip_ws_and_comments(bytes: &[u8], mut pos: usize) -> usize {
            loop {
                while pos < bytes.len()
                    && (bytes[pos] == b' '
                        || bytes[pos] == b'\t'
                        || bytes[pos] == b'\n'
                        || bytes[pos] == b'\r')
                {
                    pos += 1;
                }
                if pos + 4 <= bytes.len() && &bytes[pos..pos + 4] == b"<!--" {
                    pos += 4;
                    while pos + 3 <= bytes.len() && &bytes[pos..pos + 3] != b"-->" {
                        pos += 1;
                    }
                    pos += 3;
                } else if pos + 2 <= bytes.len() && &bytes[pos..pos + 2] == b"<?" {
                    pos += 2;
                    while pos + 2 <= bytes.len() && &bytes[pos..pos + 2] != b"?>" {
                        pos += 1;
                    }
                    pos += 2;
                } else {
                    break;
                }
            }
            pos
        }

        fn parse_node(bytes: &[u8], pos: &mut usize) -> Result<XmlNode, String> {
            *pos = skip_ws_and_comments(bytes, *pos);
            if *pos >= bytes.len() || bytes[*pos] != b'<' {
                return Err("the document does not have a root node".to_string());
            }
            *pos += 1;

            let name_start = *pos;
            while *pos < bytes.len()
                && !bytes[*pos].is_ascii_whitespace()
                && bytes[*pos] != b'>'
                && bytes[*pos] != b'/'
            {
                *pos += 1;
            }
            let name = std::str::from_utf8(&bytes[name_start..*pos])
                .map_err(|e| e.to_string())?
                .to_string();

            let mut attributes = HashMap::new();
            loop {
                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                if *pos >= bytes.len() || bytes[*pos] == b'>' || bytes[*pos] == b'/' {
                    break;
                }
                let attr_key_start = *pos;
                while *pos < bytes.len()
                    && !bytes[*pos].is_ascii_whitespace()
                    && bytes[*pos] != b'='
                    && bytes[*pos] != b'>'
                    && bytes[*pos] != b'/'
                {
                    *pos += 1;
                }
                let attr_key = std::str::from_utf8(&bytes[attr_key_start..*pos])
                    .map_err(|e| e.to_string())?
                    .to_string();

                while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                    *pos += 1;
                }
                let mut attr_val = String::new();
                if *pos < bytes.len() && bytes[*pos] == b'=' {
                    *pos += 1;
                    while *pos < bytes.len() && bytes[*pos].is_ascii_whitespace() {
                        *pos += 1;
                    }
                    if *pos < bytes.len() && (bytes[*pos] == b'"' || bytes[*pos] == b'\'') {
                        let quote = bytes[*pos];
                        *pos += 1;
                        let val_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != quote {
                            *pos += 1;
                        }
                        attr_val = std::str::from_utf8(&bytes[val_start..*pos])
                            .map_err(|e| e.to_string())?
                            .to_string();
                        if *pos < bytes.len() {
                            *pos += 1;
                        }
                    }
                }
                attributes.insert(attr_key, attr_val);
            }

            if *pos < bytes.len() && bytes[*pos] == b'/' {
                *pos += 1;
                if *pos < bytes.len() && bytes[*pos] == b'>' {
                    *pos += 1;
                }
                return Ok(XmlNode {
                    name,
                    attributes,
                    children: vec![],
                    text: String::new(),
                });
            }

            if *pos < bytes.len() && bytes[*pos] == b'>' {
                *pos += 1;
            }

            let mut children = vec![];
            let mut text = String::new();

            loop {
                *pos = skip_ws_and_comments(bytes, *pos);
                if *pos >= bytes.len() {
                    break;
                }

                if bytes[*pos] == b'<' {
                    if *pos + 1 < bytes.len() && bytes[*pos + 1] == b'/' {
                        *pos += 2;
                        let tag_close_start = *pos;
                        while *pos < bytes.len() && bytes[*pos] != b'>' {
                            *pos += 1;
                        }
                        let close_name = std::str::from_utf8(&bytes[tag_close_start..*pos])
                            .unwrap_or("")
                            .trim();
                        if close_name != name {
                            return Err(format!("expected '{}' tag, not '{}'", name, close_name));
                        }
                        if *pos < bytes.len() {
                            *pos += 1;
                        }
                        break;
                    } else {
                        children.push(parse_node(bytes, pos)?);
                    }
                } else {
                    let text_start = *pos;
                    while *pos < bytes.len() && bytes[*pos] != b'<' {
                        *pos += 1;
                    }
                    let t = std::str::from_utf8(&bytes[text_start..*pos])
                        .unwrap_or("")
                        .trim();
                    if !t.is_empty() {
                        if !text.is_empty() {
                            text.push(' ');
                        }
                        text.push_str(t);
                    }
                }
            }

            Ok(XmlNode {
                name,
                attributes,
                children,
                text,
            })
        }

        pos = skip_ws_and_comments(bytes, pos);
        let node = parse_node(bytes, &mut pos)?;
        if node.name != "device" {
            return Err(format!("expected 'device' tag, not '{}'", node.name));
        }
        Ok(node)
    }

    pub fn child_text(&self, name: &str) -> Option<String> {
        self.children
            .iter()
            .find(|c| c.name == name)
            .map(|c| c.text.clone())
    }

    pub fn children_named<'a>(&'a self, name: &'a str) -> impl Iterator<Item = &'a XmlNode> {
        self.children.iter().filter(move |c| c.name == name)
    }

    pub fn attr(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|s| s.as_str())
    }
}

pub fn parse_svd_number(s: &str) -> Result<u64, String> {
    let s = s.trim().replace('_', "");
    if let Some(stripped) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u64::from_str_radix(stripped, 16).map_err(|e| e.to_string())
    } else if let Some(stripped) = s.strip_prefix("0b").or_else(|| s.strip_prefix("0B")) {
        u64::from_str_radix(stripped, 2).map_err(|e| e.to_string())
    } else if let Some(stripped) = s.strip_prefix('#') {
        u64::from_str_radix(stripped, 2).map_err(|e| e.to_string())
    } else {
        s.parse::<u64>().map_err(|e| e.to_string())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Access {
    ReadOnly,
    WriteOnly,
    ReadWrite,
    WriteOnce,
    ReadWriteOnce,
}

impl Access {
    pub fn parse(s: &str) -> Option<Self> {
        match s.trim() {
            "read-only" => Some(Access::ReadOnly),
            "write-only" => Some(Access::WriteOnly),
            "read-write" => Some(Access::ReadWrite),
            "writeOnce" => Some(Access::WriteOnce),
            "read-writeOnce" => Some(Access::ReadWriteOnce),
            _ => None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Device {
    pub name: String,
    pub peripherals: Vec<Peripheral>,
}

#[derive(Debug, Clone)]
pub struct Peripheral {
    pub name: String,
    pub description: Option<String>,
    pub base_address: u64,
    pub derived_from: Option<String>,
    pub interrupts: Vec<Interrupt>,
    pub registers: Vec<RegisterCluster>,
}

#[derive(Debug, Clone)]
pub struct Interrupt {
    pub name: String,
    pub description: Option<String>,
    pub value: u16,
}

#[derive(Debug, Clone)]
pub enum RegisterCluster {
    Register(Register),
    Cluster(Cluster),
}

#[derive(Debug, Clone)]
pub struct DimElement {
    pub dim: u32,
    pub dim_increment: u64,
    pub dim_index: Option<Vec<String>>,
}

impl DimElement {
    pub fn parse(node: &XmlNode) -> Option<Self> {
        let dim_str = node.child_text("dim")?;
        let dim = dim_str.trim().parse::<u32>().ok()?;
        let inc_str = node.child_text("dimIncrement")?;
        let dim_increment = parse_svd_number(&inc_str).ok()?;
        let dim_index = node.child_text("dimIndex").map(|s| {
            if s.contains(',') {
                s.split(',').map(|x| x.trim().to_string()).collect()
            } else if let Some((start, end)) = s.split_once('-') {
                if let (Ok(s_num), Ok(e_num)) = (start.trim().parse::<u32>(), end.trim().parse::<u32>()) {
                    (s_num..=e_num).map(|n| n.to_string()).collect()
                } else {
                    vec![s]
                }
            } else {
                vec![s]
            }
        });
        Some(DimElement {
            dim,
            dim_increment,
            dim_index,
        })
    }
}

#[derive(Debug, Clone)]
pub struct Register {
    pub name: String,
    pub description: Option<String>,
    pub address_offset: u64,
    pub size: Option<u32>,
    pub access: Option<Access>,
    pub reset_value: Option<u64>,
    pub dim: Option<DimElement>,
    pub fields: Vec<Field>,
}

#[derive(Debug, Clone)]
pub struct Cluster {
    pub name: String,
    pub description: Option<String>,
    pub address_offset: u64,
    pub dim: Option<DimElement>,
}

#[derive(Debug, Clone)]
pub struct Field {
    pub name: String,
    pub description: Option<String>,
    pub bit_offset: u32,
    pub bit_width: u32,
    pub access: Option<Access>,
    pub enumerated_values: Vec<EnumeratedValues>,
}

#[derive(Debug, Clone)]
pub struct EnumeratedValues {
    pub name: Option<String>,
    pub values: Vec<EnumeratedValue>,
}

#[derive(Debug, Clone)]
pub struct EnumeratedValue {
    pub name: String,
    pub description: Option<String>,
    pub value: Option<u64>,
}

impl Device {
    pub fn from_xml(root: &XmlNode) -> Result<Device, String> {
        let name = root.child_text("name").ok_or("missing 'name'")?;

        let mut peripherals = vec![];
        if let Some(periphs_node) = root.children.iter().find(|c| c.name == "peripherals") {
            for p_node in periphs_node.children_named("peripheral") {
                peripherals.push(Peripheral::from_xml(p_node)?);
            }
        }

        Ok(Device {
            name,
            peripherals,
        })
    }
}

impl Peripheral {
    pub fn from_xml(node: &XmlNode) -> Result<Peripheral, String> {
        let name = node.child_text("name").ok_or("peripheral missing name")?;
        let description = node.child_text("description");
        let base_address = node
            .child_text("baseAddress")
            .and_then(|s| parse_svd_number(&s).ok())
            .unwrap_or(0);
        let derived_from = node
            .attr("derivedFrom")
            .map(|s| s.to_string())
            .or_else(|| node.child_text("derivedFrom"));

        let mut interrupts = vec![];
        for int_node in node.children_named("interrupt") {
            let int_name = int_node.child_text("name").unwrap_or_default();
            let int_desc = int_node.child_text("description");
            let int_val = int_node
                .child_text("value")
                .and_then(|s| s.parse::<u16>().ok())
                .unwrap_or(0);
            interrupts.push(Interrupt {
                name: int_name,
                description: int_desc,
                value: int_val,
            });
        }

        let mut registers = vec![];
        if let Some(regs_node) = node.children.iter().find(|c| c.name == "registers") {
            for child in &regs_node.children {
                if child.name == "register" {
                    registers.push(RegisterCluster::Register(Register::from_xml(child)?));
                } else if child.name == "cluster" {
                    registers.push(RegisterCluster::Cluster(Cluster::from_xml(child)?));
                }
            }
        }

        Ok(Peripheral {
            name,
            description,
            base_address,
            derived_from,
            interrupts,
            registers,
        })
    }
}

impl Register {
    pub fn from_xml(node: &XmlNode) -> Result<Register, String> {
        let name = node.child_text("name").ok_or("register missing name")?;
        let description = node.child_text("description");
        let address_offset = node
            .child_text("addressOffset")
            .and_then(|s| parse_svd_number(&s).ok())
            .unwrap_or(0);
        let size = node.child_text("size").and_then(|s| parse_svd_number(&s).ok()).map(|n| n as u32);
        let access = node.child_text("access").and_then(|s| Access::parse(&s));
        let reset_value = node.child_text("resetValue").and_then(|s| parse_svd_number(&s).ok());
        let dim = DimElement::parse(node);

        let mut fields = vec![];
        if let Some(fields_node) = node.children.iter().find(|c| c.name == "fields") {
            for f_node in fields_node.children_named("field") {
                fields.push(Field::from_xml(f_node)?);
            }
        }

        Ok(Register {
            name,
            description,
            address_offset,
            size,
            access,
            reset_value,
            dim,
            fields,
        })
    }
}

impl Cluster {
    pub fn from_xml(node: &XmlNode) -> Result<Cluster, String> {
        let name = node.child_text("name").ok_or("cluster missing name")?;
        let description = node.child_text("description");
        let address_offset = node
            .child_text("addressOffset")
            .and_then(|s| parse_svd_number(&s).ok())
            .unwrap_or(0);
        let dim = DimElement::parse(node);

        Ok(Cluster {
            name,
            description,
            address_offset,
            dim,
        })
    }
}

impl Field {
    pub fn from_xml(node: &XmlNode) -> Result<Field, String> {
        let name = node.child_text("name").ok_or("field missing name")?;
        let description = node.child_text("description");
        let access = node.child_text("access").and_then(|s| Access::parse(&s));

        let mut bit_offset = 0;
        let mut bit_width = 1;

        if let (Some(bo), Some(bw)) = (node.child_text("bitOffset"), node.child_text("bitWidth")) {
            bit_offset = parse_svd_number(&bo).unwrap_or(0) as u32;
            bit_width = parse_svd_number(&bw).unwrap_or(1) as u32;
        } else if let Some(br) = node.child_text("bitRange") {
            let br = br.trim_matches(|c| c == '[' || c == ']');
            if let Some((msb, lsb)) = br.split_once(':') {
                let msb_val = parse_svd_number(msb).unwrap_or(0) as u32;
                let lsb_val = parse_svd_number(lsb).unwrap_or(0) as u32;
                bit_offset = lsb_val;
                bit_width = msb_val.saturating_sub(lsb_val) + 1;
            }
        } else if let (Some(lsb), Some(msb)) = (node.child_text("lsb"), node.child_text("msb")) {
            let lsb_val = parse_svd_number(&lsb).unwrap_or(0) as u32;
            let msb_val = parse_svd_number(&msb).unwrap_or(0) as u32;
            bit_offset = lsb_val;
            bit_width = msb_val.saturating_sub(lsb_val) + 1;
        }

        let mut enumerated_values = vec![];
        for evs_node in node.children_named("enumeratedValues") {
            enumerated_values.push(EnumeratedValues::from_xml(evs_node)?);
        }

        Ok(Field {
            name,
            description,
            bit_offset,
            bit_width,
            access,
            enumerated_values,
        })
    }
}

impl EnumeratedValues {
    pub fn from_xml(node: &XmlNode) -> Result<EnumeratedValues, String> {
        let name = node.child_text("name");

        let mut values = vec![];
        for ev_node in node.children_named("enumeratedValue") {
            let name = ev_node.child_text("name").unwrap_or_default();
            let description = ev_node.child_text("description");
            let value = ev_node.child_text("value").and_then(|s| parse_svd_number(&s).ok());
            values.push(EnumeratedValue {
                name,
                description,
                value,
            });
        }

        Ok(EnumeratedValues {
            name,
            values,
        })
    }
}
